package budget

import (
	"errors"
	"math"
	"slices"
	"strings"
	"testing"
	"time"
)

var testNow = time.Date(2026, 10, 10, 20, 0, 0, 0, time.UTC)

func freshRegion(cell string, nodes, want int, pressure float64, price, projected uint64) Region {
	return Region{
		Cell: cell, Nodes: nodes, Want: want, Pressure: pressure,
		NodeMonthlyCents: price, ProjectedCents: projected, Currency: "BRL", At: testNow,
	}
}

func budgetWithCap(capCents uint64) *Budget {
	b := testBudget()
	b.MonthlyCapCents = capCents
	return &b
}

func TestAllocateWithoutBudgetHoldsEveryRegion(t *testing.T) {
	c := Allocate(nil, []Region{freshRegion("sfo", 2, 5, 0.9, 100, 10)}, nil, testNow)
	if c.State != StateNone || c.Reason != "no monthly budget is set" || c.CapCents != 0 {
		t.Fatalf("capacity = %+v", c)
	}
	if len(c.Regions) != 1 || c.Regions[0].Allowance != 2 {
		t.Fatalf("regions = %+v", c.Regions)
	}
	if err := c.Validate(); err != nil {
		t.Fatalf("unset capacity = %v", err)
	}
}

func TestAllocateHoldsEveryRegionWithAnInvalidBudget(t *testing.T) {
	c := Allocate(budgetWithCap(0), []Region{freshRegion("gru", 3, 4, 0.9, 100, 10)}, nil, testNow)
	if c.State != StateNone || !strings.Contains(c.Reason, "invalid") || c.Regions[0].Allowance != 3 ||
		math.IsNaN(c.Ratio) || c.Validate() != nil {
		t.Fatalf("capacity = %+v, %v", c, c.Validate())
	}
}

func TestAllocateHoldsEveryRegionWhenSpendIsUnknown(t *testing.T) {
	stale := freshRegion("sfo", 1, 3, 0.9, 100, 500)
	stale.At = testNow.Add(-StatusMaxAge - time.Minute)
	missing := freshRegion("sfo", 1, 3, 0.9, 100, 500)
	missing.At = time.Time{}
	otherCurrency := freshRegion("sfo", 1, 3, 0.9, 100, 500)
	otherCurrency.Currency = "USD"
	future := freshRegion("sfo", 1, 3, 0.9, 100, 500)
	future.At = testNow.Add(AllowanceMaxAge + time.Minute)
	for name, sfo := range map[string]Region{"stale": stale, "missing": missing, "other currency": otherCurrency,
		"from the future": future} {
		t.Run(name, func(t *testing.T) {
			c := Allocate(budgetWithCap(100000), []Region{freshRegion("gru", 1, 3, 0.5, 100, 200), sfo}, nil, testNow)
			if c.State != StateUnknown || !strings.Contains(c.Reason, "sfo") {
				t.Fatalf("capacity = %+v", c)
			}
			if c.ProjectedCents != 200 {
				t.Fatalf("projected = %d, want the known region's 200", c.ProjectedCents)
			}
			for _, region := range c.Regions {
				if region.Allowance != region.Nodes {
					t.Fatalf("%s allowance = %d, want its %d nodes", region.Cell, region.Allowance, region.Nodes)
				}
			}
		})
	}
}

func TestAllocateGrantsByPressureUntilTheCap(t *testing.T) {
	c := Allocate(budgetWithCap(1000), []Region{
		freshRegion("sfo", 1, 2, 0.5, 300, 100),
		freshRegion("gru", 1, 2, 0.9, 300, 100),
		freshRegion("fra", 1, 2, 0.7, 300, 100),
	}, nil, testNow)
	if c.State != StateWarn || c.ProjectedCents != 900 || c.Ratio != 0.9 || c.Headroom() != 100 {
		t.Fatalf("capacity = %+v", c)
	}
	if c.Reason != "granted gru +1, fra +1" {
		t.Fatalf("reason = %q", c.Reason)
	}
	want := map[string]int{"fra": 2, "gru": 2, "sfo": 1}
	for _, region := range c.Regions {
		if region.Allowance != want[region.Cell] {
			t.Fatalf("%s allowance = %d, want %d", region.Cell, region.Allowance, want[region.Cell])
		}
	}
	if c.Regions[0].Cell != "fra" || c.Regions[1].Cell != "gru" || c.Regions[2].Cell != "sfo" {
		t.Fatalf("regions are not sorted by cell: %+v", c.Regions)
	}
}

func TestAllocateNeverGrantsWithoutAPrice(t *testing.T) {
	c := Allocate(budgetWithCap(1000000), []Region{freshRegion("gru", 2, 5, 0.9, 0, 10)}, nil, testNow)
	if c.Regions[0].Allowance != 2 {
		t.Fatalf("allowance = %d, want 2", c.Regions[0].Allowance)
	}
}

func TestAllocateNeverGoesBelowNodes(t *testing.T) {
	c := Allocate(budgetWithCap(1000), []Region{freshRegion("gru", 4, 1, 0, 100, 10)}, nil, testNow)
	if c.Regions[0].Allowance != 4 || c.Regions[0].Want != 1 {
		t.Fatalf("region = %+v, want allowance held at 4 nodes", c.Regions[0])
	}
}

func TestAllocateStateThresholds(t *testing.T) {
	for _, tc := range []struct {
		projected uint64
		want      State
	}{
		{799, StateOK},
		{800, StateWarn},
		{999, StateWarn},
		{1000, StateOver},
		{1200, StateOver},
	} {
		c := Allocate(budgetWithCap(1000), []Region{freshRegion("gru", 1, 1, 0, 0, tc.projected)}, nil, testNow)
		if c.State != tc.want {
			t.Errorf("projected %d: state = %s, want %s", tc.projected, c.State, tc.want)
		}
	}
}

func TestAllocateSaturatesTheProjection(t *testing.T) {
	c := Allocate(budgetWithCap(1000), []Region{
		freshRegion("gru", 1, 1, 0, 0, math.MaxUint64),
		freshRegion("sfo", 1, 1, 0, 0, math.MaxUint64),
	}, nil, testNow)
	if c.State != StateOver || c.ProjectedCents != math.MaxUint64 {
		t.Fatalf("capacity = %+v", c)
	}
}

func TestAllowanceForChecksFreshnessAndCell(t *testing.T) {
	c := Allocate(budgetWithCap(1000000), []Region{freshRegion("gru", 2, 3, 0.9, 100, 10)}, nil, testNow)
	if allowance, ok := AllowanceFor(c, "gru", testNow.Add(AllowanceMaxAge)); !ok || allowance != 3 {
		t.Fatalf("fresh allowance = %d, %v", allowance, ok)
	}
	if _, ok := AllowanceFor(c, "gru", testNow.Add(AllowanceMaxAge+time.Second)); ok {
		t.Fatal("stale allowance was fresh")
	}
	if _, ok := AllowanceFor(c, "fra", testNow); ok {
		t.Fatal("allowance for a region the document does not name")
	}
}

func TestCapacityEncodeDecodeRoundTripsAndRefusesBadAllowances(t *testing.T) {
	c := Allocate(budgetWithCap(1000000), []Region{freshRegion("gru", 2, 3, 0.9, 100, 10)}, nil, testNow)
	encoded, err := c.Encode()
	if err != nil {
		t.Fatal(err)
	}
	got, err := DecodeCapacity(encoded)
	if err != nil || got.Regions[0].Allowance != 3 || got.State != StateOK || !got.At.Equal(testNow) {
		t.Fatalf("round trip = %+v, %v", got, err)
	}
	c.Regions[0].Allowance = 5
	if _, err := c.Encode(); err == nil {
		t.Fatal("allowance beyond one node encoded")
	}
	c.Regions[0].Allowance = 3
	c.State = StateNone
	if _, err := c.Encode(); err == nil {
		t.Fatal("capacity naming a cap without a budget encoded")
	}
}

func TestAlertingHysteresisOpensAtWarnAndClosesBelowClear(t *testing.T) {
	at := func(ratio float64) Capacity { return Capacity{State: StateOK, Ratio: ratio} }
	open := Alerting(false, at(0.79))
	if open {
		t.Fatal("alert opened below WarnRatio")
	}
	open = Alerting(open, at(0.8))
	if !open {
		t.Fatal("alert did not open at WarnRatio")
	}
	open = Alerting(open, at(0.77))
	if !open {
		t.Fatal("alert closed above ClearRatio")
	}
	open = Alerting(open, at(0.74))
	if open {
		t.Fatal("alert stayed open below ClearRatio")
	}
	if !Alerting(true, Capacity{State: StateUnknown, Ratio: 0.1}) || Alerting(false, Capacity{State: StateNone, Ratio: 1}) {
		t.Fatal("unknown or unset spend changed the alert")
	}
}

// allowanceOf returns cell's allowance in c, failing when c does not name it.
func allowanceOf(t *testing.T, c Capacity, cell string) RegionAllowance {
	t.Helper()
	index := slices.IndexFunc(c.Regions, func(region RegionAllowance) bool { return region.Cell == cell })
	if index < 0 {
		t.Fatalf("capacity names no %q: %+v", cell, c.Regions)
	}
	return c.Regions[index]
}

// raceCapacity grants hyd the one node a 1000-cent cap fits beside 350 cents of projected spend in each region.
func raceCapacity(t *testing.T) Capacity {
	t.Helper()
	c := Allocate(budgetWithCap(1000), []Region{freshRegion("hyd", 9, 10, 0.9, 300, 350),
		freshRegion("mad", 8, 9, 0.5, 300, 350)}, nil, testNow)
	hyd, mad := allowanceOf(t, c, "hyd"), allowanceOf(t, c, "mad")
	if hyd.Allowance != 10 || !hyd.GrantedAt.Equal(testNow) || mad.Allowance != 8 {
		t.Fatalf("first allocation = %+v", c.Regions)
	}
	return c
}

func TestReservationHoldsTheSlotWhileStatusLags(t *testing.T) {
	granted := raceCapacity(t)
	// A minute on, hyd's status still shows 9 nodes and no longer wants one, so only its reservation holds the slot.
	later := testNow.Add(time.Minute)
	lagging := []Region{freshRegion("hyd", 9, 9, 0.9, 300, 350), freshRegion("mad", 8, 9, 0.5, 300, 350)}
	if stateless := Allocate(budgetWithCap(1000), lagging, nil, later); allowanceOf(t, stateless, "mad").Allowance != 9 {
		t.Fatalf("without a reservation mad takes the slot: %+v", stateless.Regions)
	}
	c := Allocate(budgetWithCap(1000), lagging, &granted, later)
	if hyd := allowanceOf(t, c, "hyd"); hyd.Allowance != 10 || !hyd.GrantedAt.Equal(testNow) {
		t.Fatalf("hyd reservation = %+v", hyd)
	}
	if allowanceOf(t, c, "mad").Allowance != 8 {
		t.Fatalf("mad took the reserved slot: %+v", c.Regions)
	}
	if c.ProjectedCents != 1000 || c.State != StateOver {
		t.Fatalf("projected %d in state %s, want 350 + 300 reserved + 350 = 1000 over the cap", c.ProjectedCents, c.State)
	}
}

func TestReservationReleasedWhenNodesCatchUp(t *testing.T) {
	granted := raceCapacity(t)
	// hyd's status now counts its node, so the projection holds it once and mad still cannot fit.
	c := Allocate(budgetWithCap(1000), []Region{freshRegion("hyd", 10, 10, 0.9, 300, 650),
		freshRegion("mad", 8, 9, 0.5, 300, 300)}, &granted, testNow.Add(time.Minute))
	if hyd := allowanceOf(t, c, "hyd"); hyd.Allowance != 10 || !hyd.GrantedAt.IsZero() {
		t.Fatalf("hyd after catching up = %+v, want its 10 nodes and no grant", hyd)
	}
	if c.ProjectedCents != 950 || allowanceOf(t, c, "mad").Allowance != 8 {
		t.Fatalf("projected %d and mad %+v, want 950 and mad held", c.ProjectedCents, allowanceOf(t, c, "mad"))
	}
}

func TestReservationExpiresAfterReservationTTL(t *testing.T) {
	granted := raceCapacity(t)
	lagging := []Region{freshRegion("hyd", 9, 9, 0.9, 300, 350), freshRegion("mad", 8, 9, 0.5, 300, 350)}
	before := Allocate(budgetWithCap(1000), lagging, &granted, testNow.Add(ReservationTTL-time.Second))
	if allowanceOf(t, before, "hyd").Allowance != 10 || allowanceOf(t, before, "mad").Allowance != 8 {
		t.Fatalf("reservation before its TTL = %+v", before.Regions)
	}
	after := Allocate(budgetWithCap(1000), lagging, &granted, testNow.Add(ReservationTTL))
	if hyd := allowanceOf(t, after, "hyd"); hyd.Allowance != 9 || !hyd.GrantedAt.IsZero() {
		t.Fatalf("hyd after its TTL = %+v, want its 9 nodes and no grant", hyd)
	}
	if allowanceOf(t, after, "mad").Allowance != 9 {
		t.Fatalf("mad did not take the freed slot: %+v", after.Regions)
	}
}

func TestNoReservationWhenSpendIsUnknownOrBudgetUnset(t *testing.T) {
	granted := raceCapacity(t)
	later := testNow.Add(time.Minute)
	hyd := freshRegion("hyd", 9, 9, 0.9, 300, 350)
	unknownMad := freshRegion("mad", 8, 9, 0.5, 300, 350)
	unknownMad.At = time.Time{}
	for name, c := range map[string]Capacity{
		"no budget":     Allocate(nil, []Region{hyd, freshRegion("mad", 8, 9, 0.5, 300, 350)}, &granted, later),
		"unknown spend": Allocate(budgetWithCap(1000), []Region{hyd, unknownMad}, &granted, later),
	} {
		for _, region := range c.Regions {
			if region.Allowance != region.Nodes || !region.GrantedAt.IsZero() {
				t.Fatalf("%s: %s allowance %d with grant %v, want its %d nodes and no grant", name, region.Cell,
					region.Allowance, region.GrantedAt, region.Nodes)
			}
		}
	}
}

func TestCapacityValidateRequiresGrantTimeExactlyWhenGranted(t *testing.T) {
	c := raceCapacity(t)
	if err := c.Validate(); err != nil {
		t.Fatal(err)
	}
	c.Regions[0].GrantedAt = time.Time{}
	if c.Validate() == nil {
		t.Fatal("grant without a time validated")
	}
	c.Regions[0].GrantedAt = testNow
	c.Regions[1].GrantedAt = testNow
	if c.Validate() == nil {
		t.Fatal("grant time without a grant validated")
	}
}

func TestDecodeCapacityMarksInvalidDocuments(t *testing.T) {
	for name, payload := range map[string]string{"not json": "{", "fails validation": `{"schema":1}`} {
		if _, err := DecodeCapacity([]byte(payload)); !errors.Is(err, ErrInvalidCapacity) {
			t.Fatalf("%s: err = %v, want ErrInvalidCapacity", name, err)
		}
	}
}

internal/budget/budget.go.source_text:
// Package budget holds the tenancy's monthly OCI spend cap and the node
// allowances the home region's global leader derives from it. The budget is
// set once from the dashboard and stored in TS_GLOBAL_CONTROL; the leader
// writes the capacity document every minute, and every region reads both from
// its mirror. Growth is decided here, never by a region alone.
package budget

import (
	"context"
	"errors"
	"fmt"
	"regexp"
	"strings"
	"time"
	"unicode"

	"github.com/TerraScale/ts-orchestrator/internal/entityid"
	"github.com/TerraScale/ts-orchestrator/internal/globalcontrol"
	"github.com/TerraScale/ts-orchestrator/internal/protocol"
)

// Schema is the version of the budget and capacity documents.
const Schema = 1

const (
	maxDocumentBytes   = 64 << 10
	maxMonthlyCapCents = 1_000_000_000_000
	maxSetByBytes      = 254
)

var currencyCode = regexp.MustCompile(`^[A-Z]{3}$`)

// Budget is the tenancy's monthly OCI spend cap in the billing currency.
type Budget struct {
	Schema          int       `json:"schema"`
	ID              string    `json:"id"` // ULID, new on every change
	MonthlyCapCents uint64    `json:"monthly_cap_cents"`
	Currency        string    `json:"currency"` // ISO 4217, upper case
	SetBy           string    `json:"set_by"`
	SetAt           time.Time `json:"set_at"`
}

// Validate requires the current schema, a ULID, a cap of 1 to 1e12 cents, an
// ISO 4217 currency, a printable set_by and a set time.
func (b Budget) Validate() error {
	switch {
	case b.Schema != Schema:
		return fmt.Errorf("budget schema %d is not %d", b.Schema, Schema)
	case !entityid.Valid(b.ID):
		return errors.New("budget ID must be a ULID")
	case b.MonthlyCapCents == 0 || b.MonthlyCapCents > maxMonthlyCapCents:
		return errors.New("budget monthly cap must be 1 to 1e12 cents")
	case !currencyCode.MatchString(b.Currency):
		return errors.New("budget currency must be an upper case ISO 4217 code")
	case len(b.SetBy) == 0 || len(b.SetBy) > maxSetByBytes || strings.IndexFunc(b.SetBy, unicode.IsControl) >= 0:
		return errors.New("budget set_by must be 1 to 254 bytes with no control characters")
	case b.SetAt.IsZero():
		return errors.New("budget set_at is required")
	}
	return nil
}

// DecodeBudget strictly decodes and validates a stored budget.
func DecodeBudget(payload []byte) (Budget, error) {
	var b Budget
	if err := protocol.DecodeStrict(payload, &b, maxDocumentBytes); err != nil {
		return Budget{}, fmt.Errorf("decode monthly budget: %w", err)
	}
	if err := b.Validate(); err != nil {
		return Budget{}, err
	}
	return b, nil
}

// Encode validates b and returns its stored form.
func (b Budget) Encode() ([]byte, error) {
	if err := b.Validate(); err != nil {
		return nil, err
	}
	return protocol.EncodeJSON(b)
}

// Money formats cents in the currency's major unit, for example BRL 123.45.
func Money(cents uint64, currency string) string {
	return fmt.Sprintf("%s %d.%02d", currency, cents/100, cents%100)
}

// ReadBudget returns the current budget, or false when none was ever set.
func ReadBudget(ctx context.Context, reader *globalcontrol.Reader) (Budget, bool, error) {
	document, err := reader.Document(ctx, globalcontrol.KindBudget, protocol.GlobalScope)
	if errors.Is(err, globalcontrol.ErrNotFound) {
		return Budget{}, false, nil
	}
	if err != nil {
		return Budget{}, false, err
	}
	b, err := DecodeBudget(document.Payload)
	if err != nil {
		return Budget{}, false, err
	}
	return b, true, nil
}

// WriteBudget stores b as the next budget generation. Only the home region's
// global leader calls it.
func WriteBudget(ctx context.Context, writer *globalcontrol.Writer, epoch uint64, b Budget) error {
	payload, err := b.Encode()
	if err != nil {
		return err
	}
	_, err = writer.PutDocument(ctx, epoch, globalcontrol.KindBudget, protocol.GlobalScope, payload, nil)
	return err
}

internal/budget/budget_test.go.source_text:
package budget

import (
	"bytes"
	"strings"
	"testing"
	"time"

	"github.com/TerraScale/ts-orchestrator/internal/entityid"
)

func testBudget() Budget {
	return Budget{
		Schema:          Schema,
		ID:              entityid.New(),
		MonthlyCapCents: 50000,
		Currency:        "BRL",
		SetBy:           "mariogk@terrascale.tech",
		SetAt:           time.Date(2026, 10, 10, 20, 0, 0, 0, time.UTC),
	}
}

func TestBudgetValidateRefusesMalformedBudgets(t *testing.T) {
	for name, mutate := range map[string]func(*Budget){
		"schema":         func(b *Budget) { b.Schema = 2 },
		"bad ULID":       func(b *Budget) { b.ID = "not-a-ulid" },
		"zero cap":       func(b *Budget) { b.MonthlyCapCents = 0 },
		"cap too large":  func(b *Budget) { b.MonthlyCapCents = 1_000_000_000_001 },
		"lower currency": func(b *Budget) { b.Currency = "brl" },
		"short currency": func(b *Budget) { b.Currency = "BR" },
		"long currency":  func(b *Budget) { b.Currency = "BRLX" },
		"empty set_by":   func(b *Budget) { b.SetBy = "" },
		"control set_by": func(b *Budget) { b.SetBy = "mariogk\n@terrascale.tech" },
		"long set_by":    func(b *Budget) { b.SetBy = strings.Repeat("a", 255) },
		"zero set_at":    func(b *Budget) { b.SetAt = time.Time{} },
	} {
		t.Run(name, func(t *testing.T) {
			b := testBudget()
			mutate(&b)
			if err := b.Validate(); err == nil {
				t.Fatal("malformed budget validated")
			}
			if _, err := b.Encode(); err == nil {
				t.Fatal("malformed budget encoded")
			}
		})
	}
}

func TestDecodeBudgetRefusesUnknownFieldsAndInvalidBudgets(t *testing.T) {
	id := entityid.New()
	valid := `"schema":1,"id":"` + id + `","monthly_cap_cents":1,"currency":"BRL","set_by":"x","set_at":"2026-10-10T20:00:00Z"`
	if _, err := DecodeBudget([]byte("{" + valid + "}")); err != nil {
		t.Fatalf("valid budget = %v", err)
	}
	if _, err := DecodeBudget([]byte("{" + valid + `,"extra":true}`)); err == nil {
		t.Fatal("unknown field decoded")
	}
	if _, err := DecodeBudget([]byte("{" + strings.Replace(valid, `"currency":"BRL"`, `"currency":"brl"`, 1) + "}")); err == nil {
		t.Fatal("invalid currency decoded")
	}
	if _, err := DecodeBudget([]byte("not json")); err == nil {
		t.Fatal("garbage decoded")
	}
}

func TestBudgetEncodeDecodeRoundTrip(t *testing.T) {
	want := testBudget()
	encoded, err := want.Encode()
	if err != nil {
		t.Fatal(err)
	}
	got, err := DecodeBudget(encoded)
	if err != nil {
		t.Fatal(err)
	}
	if got.ID != want.ID || got.MonthlyCapCents != want.MonthlyCapCents || got.Currency != want.Currency ||
		got.SetBy != want.SetBy || !got.SetAt.Equal(want.SetAt) || got.Schema != want.Schema {
		t.Fatalf("round trip = %+v, want %+v", got, want)
	}
	again, err := got.Encode()
	if err != nil || !bytes.Equal(again, encoded) {
		t.Fatalf("re-encode = %s, %v; want %s", again, err, encoded)
	}
}

internal/budget/infrastructure_allocatio.source_text:
package budget

import (
	"context"
	"errors"
	"fmt"
	"math"
	"slices"
	"strings"
	"time"

	"github.com/TerraScale/ts-orchestrator/internal/globalcontrol"
	"github.com/TerraScale/ts-orchestrator/internal/ociregion/capacityinventory"
	"github.com/TerraScale/ts-orchestrator/internal/region"
)

// AllocateInfrastructure permits candidate planning from signed infrastructure
// headroom. It authorizes no purchase: Reserve and Revalidate require the exact
// candidate quote before every mutation. Status prices and forecasts are unused.
// Region.At is the demand observation time, not a Usage API cost timestamp.
// An error returns a held document so callers can withdraw prior planning grants.
func AllocateInfrastructure(ctx context.Context, reader *globalcontrol.Reader, proof region.VerifiedInfrastructureSpend,
	snapshot capacityinventory.Snapshot, regions []Region, prior *Capacity, now time.Time,
) (Capacity, error) {
	c := Allocate(nil, regions, prior, now)
	c.Reason = "infrastructure candidate planning is held"
	fail := func(err error) (Capacity, error) {
		c.Reason = "infrastructure candidate planning is held: " + err.Error()
		return c, err
	}
	if reader == nil {
		return fail(errors.New("home global reader is unavailable"))
	}
	stored, exists, err := ReadCapacity(ctx, reader)
	if err != nil {
		return fail(err)
	}
	if exists {
		c.Spending, c.Reservations = stored.Spending, slices.Clone(stored.Reservations)
		c.BootstrapReservedCents = max(c.BootstrapReservedCents, stored.BootstrapReservedCents)
		if stored.BootstrapSHA256 != "" {
			c.BootstrapSHA256 = stored.BootstrapSHA256
		}
	} else if c.Spending != nil || len(c.Reservations) > 0 || c.BootstrapReservedCents > 0 || c.BootstrapSHA256 != "" {
		return fail(errors.New("previous infrastructure commitments are absent from the durable ledger"))
	}
	// Pin signed bootstrap commitments even when complete cost evidence is unavailable.
	if err := retainBootstrap(&c, proof); err != nil {
		return fail(err)
	}
	monthly, hasBudget, limit, err := spendingFacts(ctx, reader, proof, snapshot, now)
	if err != nil {
		return fail(err)
	}
	limit, err = bootstrapLimit(c, proof, limit)
	if err != nil {
		return fail(err)
	}
	if limit == 0 {
		return fail(errors.New("the full infrastructure ceiling is reserved for bootstrap"))
	}
	seen := map[string]bool{}
	for _, status := range regions {
		cell := strings.ToUpper(status.Cell)
		if cell == "" || seen[cell] || status.Nodes < 0 || status.Want < 0 || math.IsNaN(status.Pressure) || math.IsInf(status.Pressure, 0) {
			c.Regions = nil
			return fail(errors.New("regional demand lacks unique cells or valid node counts and pressure"))
		}
		seen[cell] = true
	}
	total := projection(c, snapshot, "")
	if c.Spending != nil {
		// A periodic planning write cannot release an older unresolved commitment.
		total = max(total, c.Spending.ProjectedCents)
	}
	latest, found, err := ReadBudget(ctx, reader)
	if err != nil {
		return fail(err)
	}
	if found != hasBudget || found && latest != monthly {
		return fail(errors.New("tenant spending ceiling changed during infrastructure planning"))
	}
	c.CapCents, c.Currency, c.ProjectedCents = limit, proof.Currency(), total
	c.Ratio = float64(total) / float64(limit)
	switch {
	case total >= limit:
		c.State = StateOver
		c.Reason = "complete infrastructure commitments leave no headroom for candidate planning"
	case c.Ratio >= WarnRatio:
		c.State = StateWarn
	default:
		c.State = StateOK
	}
	if total < limit {
		var planned []string
		scope := proof.Footprint()
		for _, status := range regions {
			owned := slices.ContainsFunc(scope.Regions, func(s capacityinventory.RegionScope) bool { return strings.EqualFold(s.Cell, status.Cell) })
			if !owned || status.At.IsZero() || now.Sub(status.At) > AllowanceMaxAge || status.At.Sub(now) > AllowanceMaxAge || status.Want <= status.Nodes || status.Nodes+1 <= status.Nodes {
				continue
			}
			i := slices.IndexFunc(c.Regions, func(r RegionAllowance) bool { return r.Cell == status.Cell })
			c.Regions[i].Allowance, c.Regions[i].GrantedAt = status.Nodes+1, now
			planned = append(planned, status.Cell)
		}
		if len(planned) == 0 {
			c.Reason = "no authorized region has fresh demand for candidate planning"
		} else {
			slices.Sort(planned)
			c.Reason = fmt.Sprintf("provisional candidate planning for %s; exact quoted spending reservation required", strings.Join(planned, ", "))
		}
	}
	if err := c.Validate(); err != nil {
		return Capacity{}, err
	}
	return c, nil
}

internal/budget/reservation.go.source_text:
package budget

import (
	"cmp"
	"context"
	"errors"
	"fmt"
	"math"
	"regexp"
	"slices"
	"strings"
	"time"

	"github.com/TerraScale/ts-orchestrator/internal/entityid"
	"github.com/TerraScale/ts-orchestrator/internal/globalcontrol"
	"github.com/TerraScale/ts-orchestrator/internal/ociregion/capacityinventory"
	"github.com/TerraScale/ts-orchestrator/internal/protocol"
	"github.com/TerraScale/ts-orchestrator/internal/region"
)

const maxInfrastructureReservations = 64

var reservationDigest = regexp.MustCompile(`^[0-9a-f]{64}$`)

// ReservationRequest names the exact operation and immutable launch recipe.
// Authority and observed costs are obtained by the home, never accepted from a worker.
type ReservationRequest struct {
	OperationID   string    `json:"operation_id"`
	RecipeSHA256  string    `json:"recipe_sha256"`
	Cell          string    `json:"cell"`
	CompartmentID string    `json:"compartment_id"`
	Shape         string    `json:"shape"`
	OCPUs         float64   `json:"ocpus"`
	MemoryGB      float64   `json:"memory_gb"`
	BootGB        float64   `json:"boot_gb"`
	MonthlyCents  uint64    `json:"monthly_cents"`
	FactsExpireAt time.Time `json:"facts_expire_at"`
}

// Reservation remains a spending commitment after launch authorization expires.
// ResourceIDs are recorded only after positive owned-resource observations.
type Reservation struct {
	OperationID            string    `json:"operation_id"`
	RecipeSHA256           string    `json:"recipe_sha256"`
	Cell                   string    `json:"cell"`
	CompartmentID          string    `json:"compartment_id"`
	Shape                  string    `json:"shape"`
	OCPUs                  float64   `json:"ocpus"`
	MemoryGB               float64   `json:"memory_gb"`
	BootGB                 float64   `json:"boot_gb"`
	MonthlyCents           uint64    `json:"monthly_cents"`
	BudgetID               string    `json:"budget_id,omitempty"`
	InfrastructureBudgetID string    `json:"infrastructure_budget_id"`
	GrantSHA256            string    `json:"grant_sha256"`
	ScopeSHA256            string    `json:"scope_sha256"`
	ResolvedScopeSHA256    string    `json:"resolved_scope_sha256,omitempty"`
	BindingSHA256          string    `json:"binding_sha256,omitempty"`
	GrantGeneration        uint64    `json:"grant_generation,omitzero"`
	QuoteSHA256            string    `json:"quote_sha256,omitempty"`
	Currency               string    `json:"currency,omitempty"`
	TenancyID              string    `json:"tenancy_id,omitempty"`
	IssuedAt               time.Time `json:"issued_at"`
	LaunchExpiresAt        time.Time `json:"launch_expires_at"`
	ResourceIDs            []string  `json:"resource_ids,omitempty"`
	RetiredAt              time.Time `json:"retired_at,omitzero"`
}

// InfrastructureSpending records the exact complete observation used by the home.
// Tenant forecast documents preserve this ledger across periodic allocations.
type InfrastructureSpending struct {
	InfrastructureBudgetID string    `json:"infrastructure_budget_id"`
	GrantSHA256            string    `json:"grant_sha256"`
	ScopeSHA256            string    `json:"scope_sha256"`
	Currency               string    `json:"currency"`
	MonthlyLimitCents      uint64    `json:"monthly_limit_cents"`
	ProjectedCents         uint64    `json:"projected_cents"`
	ObservedAt             time.Time `json:"observed_at"`
	ExpiresAt              time.Time `json:"expires_at"`
}

func (r ReservationRequest) validate(now time.Time) error {
	if !entityid.Valid(r.OperationID) || !reservationDigest.MatchString(r.RecipeSHA256) || r.Cell == "" || r.CompartmentID == "" || !validGeometry(r.Shape, r.OCPUs, r.MemoryGB, r.BootGB) || r.MonthlyCents == 0 || r.MonthlyCents > maxMonthlyCapCents || !now.Before(r.FactsExpireAt) {
		return errors.New("capacity reservation lacks exact operation, recipe, positive known cost or current facts")
	}
	return nil
}

func validGeometry(shape string, ocpus, memoryGB, bootGB float64) bool {
	return shape != "" && ocpus > 0 && memoryGB > 0 && bootGB > 0 && !math.IsInf(ocpus, 0) && !math.IsInf(memoryGB, 0) && !math.IsInf(bootGB, 0)
}

func validateReservations(c Capacity) error {
	if c.BootstrapReservedCents > maxMonthlyCapCents || (c.BootstrapReservedCents == 0) != (c.BootstrapSHA256 == "") || c.BootstrapSHA256 != "" && !reservationDigest.MatchString(c.BootstrapSHA256) {
		return errors.New("bootstrap allocation lacks its immutable finite slice and digest")
	}
	if len(c.Reservations) > maxInfrastructureReservations {
		return errors.New("infrastructure reservation ledger exceeds its bound")
	}
	for index, r := range c.Reservations {
		if !entityid.Valid(r.OperationID) || !reservationDigest.MatchString(r.RecipeSHA256) || !reservationDigest.MatchString(r.GrantSHA256) || !reservationDigest.MatchString(r.ScopeSHA256) || r.InfrastructureBudgetID == "" || r.Cell == "" || r.CompartmentID == "" || !validGeometry(r.Shape, r.OCPUs, r.MemoryGB, r.BootGB) || r.MonthlyCents == 0 || r.MonthlyCents > maxMonthlyCapCents || r.IssuedAt.IsZero() || !r.LaunchExpiresAt.After(r.IssuedAt) || len(r.ResourceIDs) > 16 || !slices.IsSorted(r.ResourceIDs) {
			return errors.New("infrastructure reservation is invalid")
		}
		if r.GrantGeneration == 0 {
			// Historical commitments remain charged but cannot authorize a new launch.
			if r.ResolvedScopeSHA256 != "" || r.BindingSHA256 != "" || r.QuoteSHA256 != "" || r.Currency != "" || r.TenancyID != "" {
				return errors.New("historical reservation has partial original authority metadata")
			}
		} else if !reservationDigest.MatchString(r.ResolvedScopeSHA256) || !reservationDigest.MatchString(r.QuoteSHA256) || r.BindingSHA256 != "" && !reservationDigest.MatchString(r.BindingSHA256) || !currencyCode.MatchString(r.Currency) || !strings.HasPrefix(r.TenancyID, "ocid1.tenancy.") {
			return errors.New("reservation lacks exact original physical binding, grant generation or sealed quote identity")
		}
		if index > 0 && c.Reservations[index-1].OperationID >= r.OperationID {
			return errors.New("infrastructure reservations must be sorted by unique operation")
		}
		for i, id := range r.ResourceIDs {
			if id == "" || i > 0 && r.ResourceIDs[i-1] == id {
				return errors.New("reservation resource identities must be nonempty and unique")
			}
		}
		if !r.RetiredAt.IsZero() && (len(r.ResourceIDs) == 0 || r.RetiredAt.Before(r.IssuedAt)) {
			return errors.New("retired reservation lacks observed resource identities")
		}
	}
	if s := c.Spending; s != nil {
		if s.InfrastructureBudgetID == "" || !reservationDigest.MatchString(s.GrantSHA256) || !reservationDigest.MatchString(s.ScopeSHA256) || !currencyCode.MatchString(s.Currency) || s.MonthlyLimitCents > maxMonthlyCapCents || s.ObservedAt.IsZero() || !s.ExpiresAt.After(s.ObservedAt) {
			return errors.New("infrastructure spending observation is invalid")
		}
	}
	return nil
}

func spendingFacts(ctx context.Context, reader *globalcontrol.Reader, proof region.VerifiedInfrastructureSpend,
	snapshot capacityinventory.Snapshot, now time.Time,
) (Budget, bool, uint64, error) {
	if reader == nil {
		return Budget{}, false, 0, errors.New("infrastructure spending requires the home global reader")
	}
	if !proof.ValidAt(now) || proof.MonthlyLimitMinor() <= 0 || uint64(proof.MonthlyLimitMinor()) > maxMonthlyCapCents {
		return Budget{}, false, 0, errors.New("no current signed infrastructure spending authority")
	}
	if err := proof.RevalidateBindings(ctx); err != nil {
		return Budget{}, false, 0, err
	}
	if checkedAt := time.Now(); checkedAt.After(now) {
		now = checkedAt
	}
	if err := snapshot.Validate(proof.Footprint(), now); err != nil {
		return Budget{}, false, 0, err
	}
	monthly, found, err := ReadBudget(ctx, reader)
	if err != nil {
		return Budget{}, false, 0, err
	}
	limit := uint64(proof.MonthlyLimitMinor())
	if found {
		if monthly.Currency != proof.Currency() {
			return Budget{}, false, 0, errors.New("tenant and infrastructure spending currencies differ")
		}
		limit = min(limit, monthly.MonthlyCapCents)
	}
	return monthly, found, limit, nil
}

// retainBootstrap preserves the original allocation identity and the largest
// verified slice, including during held planning and historical observations.
func retainBootstrap(c *Capacity, proof region.VerifiedInfrastructureSpend) error {
	if !proof.IsVerified() || proof.BootstrapReservedMinor() <= 0 {
		return nil
	}
	reserved := uint64(proof.BootstrapReservedMinor())
	if reserved > maxMonthlyCapCents {
		return errors.New("bootstrap allocation exceeds the supported finite ceiling")
	}
	c.BootstrapReservedCents = max(c.BootstrapReservedCents, reserved)
	if c.BootstrapSHA256 == "" {
		c.BootstrapSHA256 = proof.BootstrapDigest()
	}
	return nil
}

// bootstrapLimit never refunds a signed bootstrap slice on renewal or expiry.
// A changed allocation needs provider-proven fencing, for which no release path exists.
func bootstrapLimit(c Capacity, proof region.VerifiedInfrastructureSpend, limit uint64) (uint64, error) {
	if c.BootstrapSHA256 != "" && c.BootstrapSHA256 != proof.BootstrapDigest() {
		return 0, errors.New("bootstrap allocation changed without provider-proven fencing")
	}
	reserved := max(c.BootstrapReservedCents, uint64(proof.BootstrapReservedMinor()))
	if reserved > limit {
		return 0, errors.New("full bootstrap allocation exceeds the current infrastructure ceiling")
	}
	return limit - reserved, nil
}

func allowedCompartment(scope capacityinventory.Scope, cell, compartment string) bool {
	return slices.ContainsFunc(scope.Regions, func(r capacityinventory.RegionScope) bool {
		return r.Cell == cell && slices.Contains(r.CompartmentIDs, compartment)
	})
}

func reservationIndex(c Capacity, operation string) int {
	return slices.IndexFunc(c.Reservations, func(r Reservation) bool { return r.OperationID == operation })
}

func snapshotResource(snapshot capacityinventory.Snapshot, reservation Reservation, id string) (capacityinventory.Resource, bool) {
	i := slices.IndexFunc(snapshot.Resources, func(resource capacityinventory.Resource) bool {
		return resource.ID == id && resource.Cell == reservation.Cell && resource.CompartmentID == reservation.CompartmentID &&
			resource.OperationID == reservation.OperationID && resource.RecipeSHA256 == reservation.RecipeSHA256
	})
	if i < 0 {
		return capacityinventory.Resource{}, false
	}
	return snapshot.Resources[i], true
}

func retiredResource(state string) bool {
	return state == "TERMINATED" || state == "DELETED"
}

// projection counts an unknown provider outcome for its full reserved amount.
// Expiry changes launch permission; it never releases a billable commitment.
func projection(c Capacity, snapshot capacityinventory.Snapshot, excludeOperation string) uint64 {
	total := snapshot.MonthlyCents
	for _, r := range c.Reservations {
		if !r.RetiredAt.IsZero() || r.OperationID == excludeOperation {
			continue
		}
		covered := len(r.ResourceIDs) > 0
		for _, id := range r.ResourceIDs {
			resource, found := snapshotResource(snapshot, r, id)
			if !found || retiredResource(resource.LifecycleState) {
				covered = false
				break
			}
		}
		if !covered {
			total = saturatingAdd(total, r.MonthlyCents)
		}
	}
	return total
}

// InfrastructureHeadroom filters candidates before Reserve; it never authorizes
// mutation. An exact operation retry already owns its outstanding commitment.
func InfrastructureHeadroom(ctx context.Context, reader *globalcontrol.Reader, proof region.VerifiedInfrastructureSpend,
	snapshot capacityinventory.Snapshot, operationID string, now time.Time,
) (uint64, error) {
	monthly, found, limit, err := spendingFacts(ctx, reader, proof, snapshot, now)
	if err != nil {
		return 0, err
	}
	c, _, err := ReadCapacity(ctx, reader)
	if err != nil {
		return 0, err
	}
	limit, err = bootstrapLimit(c, proof, limit)
	if err != nil {
		return 0, err
	}
	exclude := ""
	if i := reservationIndex(c, operationID); i >= 0 {
		tenantID := ""
		if found {
			tenantID = monthly.ID
		}
		if err := currentReservation(c.Reservations[i], tenantID, proof, now); err != nil {
			return 0, err
		}
		exclude = operationID
	}
	total := projection(c, snapshot, exclude)
	latest, hasBudget, err := ReadBudget(ctx, reader)
	if err != nil {
		return 0, err
	}
	if hasBudget != found || hasBudget && latest != monthly {
		return 0, errors.New("tenant spending ceiling changed during candidate selection")
	}
	if total >= limit {
		return 0, nil
	}
	return limit - total, nil
}

// Reserve appends an idempotent exact-candidate commitment under the home CAS.
// A tenant budget can tighten the signed infrastructure ceiling, never expand it.
func Reserve(ctx context.Context, reader *globalcontrol.Reader, writer *globalcontrol.Writer, epoch uint64,
	request ReservationRequest, proof region.VerifiedInfrastructureSpend, quote capacityinventory.Quote, snapshot capacityinventory.Snapshot, now time.Time,
) (Reservation, error) {
	if err := request.validate(now); err != nil {
		return Reservation{}, err
	}
	if !allowedCompartment(proof.Footprint(), request.Cell, request.CompartmentID) {
		return Reservation{}, errors.New("candidate is outside the signed infrastructure footprint")
	}
	if err := quotedCandidate(proof, quote, request.Cell, request.CompartmentID, request.Shape, request.OCPUs, request.MemoryGB, request.BootGB, request.MonthlyCents, now); err != nil {
		return Reservation{}, err
	}
	var result Reservation
	err := changeReservations(ctx, reader, writer, epoch, proof, snapshot, now, true, func(c *Capacity, monthly Budget, found bool) error {
		checkedAt := time.Now()
		if now.After(checkedAt) {
			checkedAt = now
		}
		if err := request.validate(checkedAt); err != nil {
			return err
		}
		if err := quotedCandidate(proof, quote, request.Cell, request.CompartmentID, request.Shape, request.OCPUs, request.MemoryGB, request.BootGB, request.MonthlyCents, checkedAt); err != nil {
			return err
		}
		tenantID := ""
		if found {
			tenantID = monthly.ID
		}
		if i := reservationIndex(*c, request.OperationID); i >= 0 {
			r := c.Reservations[i]
			if r.RecipeSHA256 != request.RecipeSHA256 || r.MonthlyCents != request.MonthlyCents || r.Cell != request.Cell || r.CompartmentID != request.CompartmentID || r.Shape != request.Shape || r.OCPUs != request.OCPUs || r.MemoryGB != request.MemoryGB || r.BootGB != request.BootGB {
				return errors.New("operation is already reserved for a different candidate or price")
			}
			if err := currentReservation(r, tenantID, proof, checkedAt); err != nil {
				return err
			}
			result = r
			return nil
		}
		if len(c.Reservations) >= maxInfrastructureReservations {
			// shortcut: unknown commitments remain charged; add provider-proven cancellation before reclaiming entries.
			return errors.New("infrastructure reservation ledger is full")
		}
		expires := minTime(request.FactsExpireAt, proof.ExpiresAt(), quote.ExpiresAt(), snapshot.ExpiresAt, now.Add(ReservationTTL))
		result = Reservation{OperationID: request.OperationID, RecipeSHA256: request.RecipeSHA256, Cell: request.Cell,
			CompartmentID: request.CompartmentID, Shape: request.Shape, OCPUs: request.OCPUs, MemoryGB: request.MemoryGB, BootGB: request.BootGB, MonthlyCents: request.MonthlyCents, BudgetID: tenantID,
			InfrastructureBudgetID: proof.BudgetID(), GrantSHA256: proof.GrantDigest(), ScopeSHA256: proof.ScopeDigest(),
			ResolvedScopeSHA256: proof.PhysicalScopeDigest(), BindingSHA256: proof.BindingDigest(), GrantGeneration: proof.Generation(), QuoteSHA256: quote.SHA256(), Currency: proof.Currency(), TenancyID: proof.Footprint().TenancyID, IssuedAt: now, LaunchExpiresAt: expires}
		c.Reservations = append(slices.Clone(c.Reservations), result)
		slices.SortFunc(c.Reservations, func(a, b Reservation) int { return cmp.Compare(a.OperationID, b.OperationID) })
		return nil
	})
	return result, err
}

func currentReservation(r Reservation, tenantID string, proof region.VerifiedInfrastructureSpend, now time.Time) error {
	if !r.RetiredAt.IsZero() || !now.Before(r.LaunchExpiresAt) || r.BudgetID != tenantID || r.InfrastructureBudgetID != proof.BudgetID() || r.GrantSHA256 != proof.GrantDigest() || r.ScopeSHA256 != proof.ScopeDigest() || r.ResolvedScopeSHA256 != proof.PhysicalScopeDigest() || r.BindingSHA256 != proof.BindingDigest() || r.GrantGeneration != proof.Generation() || !reservationDigest.MatchString(r.QuoteSHA256) || r.Currency != proof.Currency() || r.TenancyID != proof.Footprint().TenancyID {
		return errors.New("reservation is retired, expired or differs from current spending authority")
	}
	return nil
}

// Revalidate checks the durable receipt against current authority and complete costs.
// The caller also fences its own regional authority immediately before mutation.
func Revalidate(ctx context.Context, reader *globalcontrol.Reader, receipt Reservation,
	proof region.VerifiedInfrastructureSpend, quote capacityinventory.Quote, snapshot capacityinventory.Snapshot, now time.Time,
) error {
	if err := quotedCandidate(proof, quote, receipt.Cell, receipt.CompartmentID, receipt.Shape, receipt.OCPUs, receipt.MemoryGB, receipt.BootGB, receipt.MonthlyCents, now); err != nil {
		return err
	}
	monthly, found, limit, err := spendingFacts(ctx, reader, proof, snapshot, now)
	if err != nil {
		return err
	}
	c, exists, err := ReadCapacity(ctx, reader)
	if err != nil {
		return err
	}
	if !exists {
		return errors.New("capacity reservation ledger is unavailable")
	}
	limit, err = bootstrapLimit(c, proof, limit)
	if err != nil {
		return err
	}
	i := reservationIndex(c, receipt.OperationID)
	if i < 0 {
		return errors.New("capacity reservation was never committed")
	}
	r := c.Reservations[i]
	if r.RecipeSHA256 != receipt.RecipeSHA256 || r.MonthlyCents != receipt.MonthlyCents || r.Cell != receipt.Cell || r.CompartmentID != receipt.CompartmentID || r.Shape != receipt.Shape || r.OCPUs != receipt.OCPUs || r.MemoryGB != receipt.MemoryGB || r.BootGB != receipt.BootGB || r.InfrastructureBudgetID != receipt.InfrastructureBudgetID || r.GrantSHA256 != receipt.GrantSHA256 || r.ScopeSHA256 != receipt.ScopeSHA256 || r.ResolvedScopeSHA256 != receipt.ResolvedScopeSHA256 || r.BindingSHA256 != receipt.BindingSHA256 || r.GrantGeneration != receipt.GrantGeneration || r.QuoteSHA256 != receipt.QuoteSHA256 || r.Currency != receipt.Currency || r.TenancyID != receipt.TenancyID || r.BudgetID != receipt.BudgetID || !r.IssuedAt.Equal(receipt.IssuedAt) || !r.LaunchExpiresAt.Equal(receipt.LaunchExpiresAt) {
		return errors.New("capacity receipt differs from its durable reservation")
	}
	tenantID := ""
	if found {
		tenantID = monthly.ID
	}
	if err := currentReservation(r, tenantID, proof, now); err != nil {
		return err
	}
	if projection(c, snapshot, "") > limit {
		return errors.New("complete infrastructure commitments exceed the current spending ceiling")
	}
	latest, hasBudget, err := ReadBudget(ctx, reader)
	if err != nil {
		return err
	}
	if hasBudget != found || hasBudget && latest != monthly {
		return errors.New("tenant spending ceiling changed during reservation revalidation")
	}
	// Independent SDK reads can outlast the facts checked before those reads.
	checkedAt := time.Now()
	if now.After(checkedAt) {
		checkedAt = now
	}
	if err := currentReservation(r, tenantID, proof, checkedAt); err != nil {
		return err
	}
	if err := snapshot.Validate(proof.Footprint(), checkedAt); err != nil {
		return err
	}
	return quotedCandidate(proof, quote, receipt.Cell, receipt.CompartmentID, receipt.Shape, receipt.OCPUs, receipt.MemoryGB, receipt.BootGB, receipt.MonthlyCents, checkedAt)
}

func quotedCandidate(proof region.VerifiedInfrastructureSpend, quote capacityinventory.Quote,
	cell, compartment, shape string, ocpus, memoryGB, bootGB float64, monthlyCents uint64, now time.Time,
) error {
	if err := quote.Validate(proof.Footprint(), cell, compartment, shape, ocpus, memoryGB, bootGB, now); err != nil {
		return err
	}
	if quote.Currency() != proof.Currency() || quote.MonthlyCents() != monthlyCents {
		return errors.New("candidate price differs from the sealed quote or spending currency")
	}
	return nil
}

// Observe binds an operation to actual priced resources. Replays must name the
// same identities. Retirement requires positive terminal observations for all IDs.
func Observe(ctx context.Context, reader *globalcontrol.Reader, writer *globalcontrol.Writer, epoch uint64,
	operationID string, resourceIDs []string, proof region.VerifiedInfrastructureSpend, snapshot capacityinventory.Snapshot, now time.Time,
) (Reservation, error) {
	ids := slices.Clone(resourceIDs)
	slices.Sort(ids)
	if len(ids) == 0 || len(ids) > 16 || slices.Contains(ids, "") || len(slices.Compact(slices.Clone(ids))) != len(ids) {
		return Reservation{}, errors.New("observed commitment needs unique exact resource identities")
	}
	var result Reservation
	err := changeReservations(ctx, reader, writer, epoch, proof, snapshot, now, false, func(c *Capacity, _ Budget, _ bool) error {
		i := reservationIndex(*c, operationID)
		if i < 0 {
			return errors.New("no reserved operation matches the observed resources")
		}
		r := c.Reservations[i]
		if len(r.ResourceIDs) > 0 && !slices.Equal(r.ResourceIDs, ids) {
			return errors.New("reservation already names different resources")
		}
		// A node commitment includes its boot volume; an instance alone cannot retire it.
		associated := []string{}
		instance, boot := false, false
		for _, resource := range snapshot.Resources {
			if resource.OperationID == r.OperationID && resource.RecipeSHA256 == r.RecipeSHA256 && resource.Cell == r.Cell && resource.CompartmentID == r.CompartmentID {
				associated = append(associated, resource.ID)
				instance = instance || strings.HasPrefix(resource.ID, "ocid1.instance.")
				boot = boot || strings.HasPrefix(resource.ID, "ocid1.bootvolume.")
			}
		}
		slices.Sort(associated)
		if !instance || !boot || !slices.Equal(ids, associated) {
			return errors.New("observation must name every exact node and boot resource of this operation")
		}
		retired := true
		for _, id := range ids {
			resource, ok := snapshotResource(snapshot, r, id)
			if !ok {
				return fmt.Errorf("resource %s lacks positive owned-resource cost evidence", id)
			}
			retired = retired && retiredResource(resource.LifecycleState)
		}
		r.ResourceIDs = ids
		if retired && r.RetiredAt.IsZero() {
			r.RetiredAt = now
		}
		c.Reservations = slices.Clone(c.Reservations)
		c.Reservations[i] = r
		result = r
		return nil
	})
	return result, err
}

func changeReservations(ctx context.Context, reader *globalcontrol.Reader, writer *globalcontrol.Writer, epoch uint64,
	proof region.VerifiedInfrastructureSpend, snapshot capacityinventory.Snapshot, now time.Time, admit bool,
	change func(*Capacity, Budget, bool) error,
) error {
	if writer == nil || reader == nil {
		return errors.New("infrastructure reservations require the home global writer")
	}
	reader = &writer.Reader
	for range 8 {
		var monthly Budget
		var found bool
		var limit uint64
		var err error
		if admit {
			monthly, found, limit, err = spendingFacts(ctx, reader, proof, snapshot, now)
		} else {
			// Financial expiry prevents purchases, not observations of owned resources.
			if !proof.IsVerified() {
				return errors.New("owned-resource observation lacks signed footprint proof")
			}
			err = snapshot.ValidateOwned(proof.Footprint(), now)
			if err == nil {
				monthly, found, err = ReadBudget(ctx, reader)
			}
			if proof.MonthlyLimitMinor() > 0 {
				limit = uint64(proof.MonthlyLimitMinor())
			}
			if found && monthly.Currency == proof.Currency() {
				limit = min(limit, monthly.MonthlyCapCents)
			}
		}
		if err != nil {
			return err
		}
		c, exists, err := ReadCapacity(ctx, reader)
		if err != nil {
			return err
		}
		var expected []byte
		if exists {
			expected, err = c.Encode()
			if err != nil {
				return err
			}
		} else {
			c = Capacity{Schema: Schema, At: now, State: StateNone, Reason: "infrastructure commitments; tenant budget is unset"}
		}
		if admit {
			limit, err = bootstrapLimit(c, proof, limit)
			if err != nil {
				return err
			}
		} else {
			reserved := max(c.BootstrapReservedCents, uint64(proof.BootstrapReservedMinor()))
			limit -= min(limit, reserved)
		}
		if err := retainBootstrap(&c, proof); err != nil {
			return err
		}
		if err := change(&c, monthly, found); err != nil {
			return err
		}
		total := projection(c, snapshot, "")
		if admit && total > limit {
			return fmt.Errorf("infrastructure commitment %d exceeds authorized monthly ceiling %d", total, limit)
		}
		c.Spending = &InfrastructureSpending{InfrastructureBudgetID: proof.BudgetID(), GrantSHA256: proof.GrantDigest(), ScopeSHA256: proof.ScopeDigest(), Currency: proof.Currency(), MonthlyLimitCents: limit, ProjectedCents: total, ObservedAt: snapshot.ObservedAt, ExpiresAt: snapshot.ExpiresAt}
		c.ProjectedCents = max(c.ProjectedCents, total)
		if c.CapCents > 0 {
			c.Ratio = float64(c.ProjectedCents) / float64(c.CapCents)
			if c.ProjectedCents >= c.CapCents {
				c.State = StateOver
			} else if c.State == StateOK && c.Ratio >= WarnRatio {
				c.State = StateWarn
			}
		}
		payload, err := c.Encode()
		if err != nil {
			return err
		}
		_, err = writer.PutDocument(ctx, epoch, globalcontrol.KindCapacity, protocol.GlobalScope, payload, func(stored []byte) error {
			if !sameCapacity(stored, expected) {
				return globalcontrol.ErrConflict
			}
			latest, hasBudget, readErr := ReadBudget(ctx, reader)
			if readErr != nil {
				return readErr
			}
			if hasBudget != found || hasBudget && latest != monthly {
				return globalcontrol.ErrConflict
			}
			return nil
		})
		if errors.Is(err, globalcontrol.ErrConflict) {
			continue
		}
		if err == nil {
			// An identical document retry can return before PutDocument's admission callback.
			latest, hasBudget, readErr := ReadBudget(ctx, reader)
			if readErr != nil {
				return readErr
			}
			if hasBudget != found || hasBudget && latest != monthly {
				continue
			}
		}
		return err
	}
	return globalcontrol.ErrConflict
}

func minTime(times ...time.Time) time.Time {
	result := times[0]
	for _, at := range times[1:] {
		if at.Before(result) {
			result = at
		}
	}
	return result
}

