package capacity

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"text/tabwriter"
	"time"

	"github.com/TerraScale/ts-orchestrator/internal/ociclient"
	"github.com/TerraScale/ts-orchestrator/internal/vaultsecret"
)

// ReadSecret uses the operator's OCI profile, not an instance principal on a laptop.
func ReadSecret(ctx context.Context, ref vaultsecret.Ref) (string, error) {
	values, err := vaultsecret.Resolve(ctx, map[string]vaultsecret.Ref{"value": ref}, func(region string) (vaultsecret.BundleClient, error) {
		factory, err := ociclient.OperatorConfig(region)
		if err != nil {
			return nil, err
		}
		return vaultsecret.SecretsClient(factory)
	})
	return values["value"], err
}

type Client struct {
	URLs  []string
	Token string
	HTTP  *http.Client
}

func (c Client) Query(ctx context.Context, region string, from, to time.Time) (Usage, error) {
	if err := ValidateWindow(region, from, to, time.Now()); err != nil {
		return Usage{}, err
	}
	if len(c.Token) < 32 || len(c.Token) > 4096 || strings.ContainsAny(c.Token, "\r\n") {
		return Usage{}, errors.New("usage requires a valid bearer token")
	}
	hc := http.Client{Timeout: 15 * time.Second}
	if c.HTTP != nil {
		hc = *c.HTTP
	} else {
		transport := &http.Transport{Proxy: nil, IdleConnTimeout: 30 * time.Second}
		defer transport.CloseIdleConnections()
		hc.Transport = transport
	}
	hc.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	ctx, cancel := context.WithCancel(ctx)
	var pending sync.WaitGroup
	defer func() { cancel(); pending.Wait() }()
	requests := make([]*http.Request, 0, len(c.URLs))
	for _, base := range c.URLs {
		u, err := url.Parse(base)
		if err != nil || u.User != nil || u.RawQuery != "" || u.Fragment != "" || u.Host == "" || (u.Scheme != "https" && u.Scheme != "http") {
			return Usage{}, errors.New("invalid usage URL")
		}
		if u.Scheme == "http" && u.Hostname() != "localhost" && u.Hostname() != "127.0.0.1" && !strings.HasSuffix(u.Hostname(), ".nb.ts.internal") {
			return Usage{}, errors.New("HTTP usage URL must use loopback or the encrypted NetBird overlay")
		}
		u.Path = strings.TrimRight(u.Path, "/") + "/v1/usage"
		u.RawQuery = url.Values{"region": {region}, "from": {from.UTC().Format(time.RFC3339Nano)}, "to": {to.UTC().Format(time.RFC3339Nano)}}.Encode()
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
		if err != nil {
			return Usage{}, err
		}
		req.Header.Set("Authorization", "Bearer "+c.Token)
		requests = append(requests, req)
	}
	results := make(chan *Usage, len(requests))
	for _, req := range requests {
		pending.Go(func() {
			var result *Usage
			defer func() { results <- result }()
			response, err := hc.Do(req)
			if err != nil {
				return
			}
			defer response.Body.Close()
			var usage Usage
			err = json.NewDecoder(io.LimitReader(response.Body, 8<<20)).Decode(&usage)
			if response.StatusCode == 200 && err == nil && usage.Region == region && usage.From.Equal(from) && usage.To.Equal(to) {
				result = &usage
			}
		})
	}
	var best *Usage
	for range requests {
		var result *Usage
		select {
		case <-ctx.Done():
			return Usage{}, ctx.Err()
		case result = <-results:
		}
		if err := ctx.Err(); err != nil {
			return Usage{}, err
		}
		if result == nil {
			continue
		}
		if result.Complete {
			return *result, nil
		}
		if best == nil || len(result.Replicas) > len(best.Replicas) {
			best = result
		}
	}
	if err := ctx.Err(); err != nil {
		return Usage{}, err
	}
	if best != nil {
		return *best, nil
	}
	return Usage{}, errors.New("no regional controller returned usage; check Vault token, connectivity and binary version")
}

func Run(ctx context.Context, args []string, out io.Writer) error {
	flags := flag.NewFlagSet("usage", flag.ContinueOnError)
	flags.SetOutput(out)
	region := flags.String("region", "", "gru or sfo")
	fromText := flags.String("from", "", "RFC3339 window start")
	toText := flags.String("to", "", "RFC3339 window end")
	format := flags.String("format", "table", "table or json")
	base := flags.String("url", "", "controller origin; default tries all three regional controllers")
	tokenFile := flags.String("token-file", "", "0600 bearer token file")
	vault := flags.String("token-vault", "", "regional OCI Vault OCID")
	name := flags.String("token-name", "", "dashboard bearer token secret name")
	configFile := flags.String("config", "", "shared benchmark.json config, default ~/.config/ts-orch/benchmark.json")
	if err := flags.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return nil
		}
		return err
	}
	if flags.NArg() != 0 {
		return errors.New("usage accepts flags only")
	}
	from, err := time.Parse(time.RFC3339Nano, *fromText)
	if err != nil {
		return errors.New("--from requires RFC3339")
	}
	to, err := time.Parse(time.RFC3339Nano, *toText)
	if err != nil {
		return errors.New("--to requires RFC3339")
	}
	if err := ValidateWindow(*region, from, to, time.Now()); err != nil {
		return err
	}
	if *format != "json" && *format != "table" {
		return errors.New("--format must be json or table")
	}
	var token string
	urls := RegionalURLs(*region)
	if *tokenFile != "" {
		info, err := os.Lstat(*tokenFile)
		if err != nil || !info.Mode().IsRegular() || info.Mode().Perm()&0077 != 0 || info.Size() > 4096 {
			return errors.New("token file must be a private regular file of at most 4096 bytes")
		}
		data, err := os.ReadFile(*tokenFile)
		if err != nil {
			return err
		}
		token = strings.TrimSpace(string(data))
	} else {
		if *vault == "" && *name == "" {
			if *configFile == "" {
				home, err := os.UserHomeDir()
				if err != nil {
					return err
				}
				*configFile = filepath.Join(home, ".config", "ts-orch", "benchmark.json")
			}
			data, err := os.ReadFile(*configFile)
			if err != nil {
				return fmt.Errorf("read usage config: %w", err)
			}
			if len(data) > 1<<20 {
				return errors.New("usage config exceeds 1 MiB")
			}
			var config struct {
				Regions map[string]struct {
					URLs  []string        `json:"usage_urls"`
					Token vaultsecret.Ref `json:"usage_token"`
				} `json:"regions"`
			}
			if err := json.Unmarshal(data, &config); err != nil {
				return err
			}
			settings, ok := config.Regions[*region]
			if !ok {
				return errors.New("usage config has no selected region")
			}
			*vault, *name = settings.Token.Vault, settings.Token.Name
			if len(settings.URLs) > 0 {
				urls = settings.URLs
			}
		}
		token, err = ReadSecret(ctx, vaultsecret.Ref{Vault: *vault, Name: *name})
		if err != nil {
			return err
		}
	}
	if *base != "" {
		urls = []string{*base}
	}
	result, err := (Client{URLs: urls, Token: token}).Query(ctx, *region, from, to)
	if err != nil {
		return err
	}
	if *format == "json" {
		return json.NewEncoder(out).Encode(result)
	}
	return WriteTable(out, result)
}

func RegionalURLs(region string) []string {
	var urls []string
	for i := 1; i <= 3; i++ {
		urls = append(urls, fmt.Sprintf("http://ts-%s-%d.nb.ts.internal:9463", region, i))
	}
	return urls
}

func WriteTable(out io.Writer, result Usage) error {
	w := tabwriter.NewWriter(out, 0, 4, 2, ' ', 0)
	_, err := fmt.Fprintf(w, "REGION\tCOMPLETE\tFROM\tTO\n%s\t%t\t%s\t%s\n", result.Region, result.Complete, result.From.Format(time.RFC3339), result.To.Format(time.RFC3339))
	if err != nil {
		return err
	}
	_, err = fmt.Fprintln(w, "ENTITY\tCPU USED/REQUEST/LIMIT/FREE cores\tMEM USED/REQUEST/LIMIT/FREE MiB")
	if err != nil {
		return err
	}
	for _, rows := range [][]Row{result.Nodes, result.Services} {
		for _, row := range rows {
			name := row.Node
			if row.Service != "" {
				name = row.Environment + "/" + row.Service
			}
			if _, err := fmt.Fprintf(w, "%s\t%s\t%s\n", name, resourceText(row.CPU, 1), resourceText(row.Memory, 1<<20)); err != nil {
				return err
			}
		}
	}
	if len(result.Missing) > 0 {
		if _, err := fmt.Fprintf(w, "MISSING\t%s\n", strings.Join(result.Missing, ",")); err != nil {
			return err
		}
	}
	return w.Flush()
}

func resourceText(r Resource, divisor float64) string {
	var values []string
	for _, stat := range []*Stats{r.Usage, r.Request, r.Limit, r.Headroom} {
		if stat == nil {
			values = append(values, "?")
			continue
		}
		value := stat.Mean
		if stat == r.Headroom {
			value = stat.Min
		}
		text := fmt.Sprintf("%.2f", value/divisor)
		if !stat.Complete {
			text += "*"
		}
		values = append(values, text)
	}
	return strings.Join(values, " / ")
}

internal/capacity/coverage_review_test.g.source_text:
package capacity

import (
	"testing"
	"time"

	"github.com/TerraScale/ts-orchestrator/internal/hostload"
	"github.com/TerraScale/ts-orchestrator/internal/observability"
)

func TestServiceCoverageRequiresAnOverlappingRange(t *testing.T) {
	from := time.Now().UTC().Add(-time.Minute)
	to := from.Add(15 * time.Second)
	a := []observability.Point{{Time: from, Value: 1, Min: 1, Max: 1}, {Time: from.Add(5 * time.Second), Value: 1, Min: 1, Max: 1}}
	for _, offset := range []time.Duration{4, 5, 6} {
		b := []observability.Point{{Time: from.Add(offset * time.Second), Value: 2, Min: 2, Max: 2}, {Time: from.Add((offset + 5) * time.Second), Value: 2, Min: 2, Max: 2}}
		replicas := []*replicaSeries{
			{active: []hostload.UsageInterval{{From: from, To: to}}, metrics: map[string][]observability.Point{"cpu_usage": a}},
			{active: []hostload.UsageInterval{{From: from, To: to}}, metrics: map[string][]observability.Point{"cpu_usage": b}},
		}
		total := aggregateMetric(replicas, "cpu_usage", from, to)
		if total == nil || total.Complete != (offset == 4) || total.Mean != 3 {
			t.Fatalf("offset %s: aggregate coverage = %+v", offset*time.Second, total)
		}
	}
}

func TestIncompleteServiceCoverageMakesUsageIncomplete(t *testing.T) {
	s := NewStore("gru")
	from := time.Now().UTC().Truncate(5 * time.Second).Add(-time.Minute)
	to := from.Add(15 * time.Second)
	for _, node := range []string{"a", "b"} {
		offset := 0
		if node == "b" {
			offset = 6
		}
		for _, second := range []int{offset, offset + 5} {
			appendResourceSample(s, from.Add(time.Duration(second)*time.Second), node, 3)
		}
	}
	usage, err := s.Query(from, to, fullWindowInventory(from, to, "", "a", "b", "a/api", "b/api"))
	if err != nil || len(usage.Services) != 1 || usage.Complete || rowComplete(usage.Services[0]) {
		t.Fatalf("non-overlapping service coverage claimed complete: %+v %v", usage, err)
	}
	for _, replica := range usage.Replicas {
		if !rowComplete(replica) {
			t.Fatalf("individual replica should cover the short window: %+v", replica)
		}
	}
}

func TestMeasurementQueryExcludesBoundarySampleSpikes(t *testing.T) {
	s := NewStore("gru")
	base := time.Now().UTC().Truncate(5 * time.Second).Add(-time.Minute)
	appendResourceSample(s, base.Add(500*time.Millisecond), "a", 0.01)
	appendResourceSample(s, base.Add(2*time.Second), "a", 3)
	for second := 5; second <= 30; second += 5 {
		appendResourceSample(s, base.Add(time.Duration(second)*time.Second), "a", 3)
	}
	appendResourceSample(s, base.Add(32*time.Second), "a", 0.01)
	usage, err := s.Query(base.Add(time.Second), base.Add(31*time.Second), fullWindowInventory(base.Add(time.Second), base.Add(31*time.Second), "", "a", "a/api"))
	if err != nil || !usage.Complete || len(usage.Nodes) != 1 || usage.Nodes[0].CPU.Headroom.Min != 3 || usage.Replicas[0].CPU.Headroom.Min != 3 {
		t.Fatalf("warmup/cleanup samples contaminated measurement headroom: %+v %v", usage, err)
	}
}

func appendResourceSample(s *Store, at time.Time, node string, headroom float64) {
	var samples []observability.Sample
	for _, service := range []string{"", "api"} {
		for metric, value := range map[string]float64{"cpu_usage": 1, "cpu_request": 2, "cpu_limit": 4, "cpu_headroom": headroom, "memory_usage": 100, "memory_request": 200, "memory_limit": 400, "memory_headroom": 300} {
			samples = append(samples, observability.Sample{Metric: "capacity_" + metric, Labels: observability.L("node", node, "service", service), Value: value})
		}
	}
	s.History.Append(at, samples)
}

internal/capacity/failover_review_test.g.source_text:
package capacity

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync/atomic"
	"testing"
	"time"
)

func TestUsageQueriesHealthyThirdControllerWithinCallerDeadline(t *testing.T) {
	_, from, to := fixture(t)
	started := make(chan struct{}, 2)
	var canceled atomic.Int32
	stall := http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
		started <- struct{}{}
		<-r.Context().Done()
		canceled.Add(1)
	})
	first, second := httptest.NewServer(stall), httptest.NewServer(stall)
	defer first.Close()
	defer second.Close()
	third := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		for range 2 {
			select {
			case <-started:
			case <-r.Context().Done():
				return
			}
		}
		_ = json.NewEncoder(w).Encode(Usage{Region: "gru", From: from, To: to, Complete: true})
	}))
	defer third.Close()
	ctx, cancel := context.WithTimeout(t.Context(), time.Second)
	defer cancel()
	client := Client{URLs: []string{first.URL, second.URL, third.URL}, Token: strings.Repeat("a", 32)}
	usage, err := client.Query(ctx, "gru", from, to)
	if err != nil || !usage.Complete || ctx.Err() != nil {
		t.Fatalf("healthy third controller was blocked by earlier attempts: %+v %v", usage, err)
	}
	first.Close()
	second.Close()
	if canceled.Load() != 2 {
		t.Fatalf("remaining controller requests were not canceled: %d", canceled.Load())
	}
}

func TestConcurrentUsageSelectsBestPartialAndHonorsCancellation(t *testing.T) {
	_, from, to := fixture(t)
	for _, mode := range []string{"partial", "canceled"} {
		t.Run(mode, func(t *testing.T) {
			var servers []*httptest.Server
			client := Client{Token: strings.Repeat("a", 32)}
			for count := 1; count <= 3; count++ {
				server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
					if mode == "canceled" {
						<-r.Context().Done()
						return
					}
					_ = json.NewEncoder(w).Encode(Usage{Region: "gru", From: from, To: to, Replicas: make([]Row, count)})
				}))
				servers = append(servers, server)
				client.URLs = append(client.URLs, server.URL)
			}
			defer func() {
				for _, server := range servers {
					server.Close()
				}
			}()
			timeout := time.Second
			if mode == "canceled" {
				timeout = 100 * time.Millisecond
			}
			ctx, cancel := context.WithTimeout(t.Context(), timeout)
			defer cancel()
			usage, err := client.Query(ctx, "gru", from, to)
			if mode == "partial" && (err != nil || usage.Complete || len(usage.Replicas) != 3) {
				t.Fatalf("best partial answer was lost: %+v %v", usage, err)
			}
			if mode == "canceled" && !errors.Is(err, context.DeadlineExceeded) {
				t.Fatalf("caller deadline was lost: %v", err)
			}
		})
	}
}

