package capacitysim

import (
	"math"
	"math/rand/v2"
	"slices"
	"time"
)

// demand is one region's load in node units: a base level, step changes and a daily swing.
type demand struct {
	base, swing, phase float64
	steps              []demandStep // sorted by at
}

type demandStep struct {
	at time.Time
	to float64
}

// newDemand draws one region's profile from rng. The ramp region climbs past the 12-node ceiling and stays there.
func newDemand(rng *rand.Rand, start time.Time, ramp bool) demand {
	d := demand{base: 3 + 3.5*rng.Float64(), swing: 0.5 + rng.Float64(), phase: 2 * math.Pi * rng.Float64()}
	if ramp {
		for i := range 13 {
			at := start.Add(4*time.Hour + time.Duration(i)*30*time.Minute)
			d.steps = append(d.steps, demandStep{at: at, to: 4 + float64(i)*10/12})
		}
		return d
	}
	for range 2 {
		at := start.Add(time.Duration(rng.Int64N(int64(40 * time.Hour))))
		d.steps = append(d.steps, demandStep{at: at, to: 1.5 + 6*rng.Float64()})
	}
	slices.SortFunc(d.steps, func(a, b demandStep) int { return a.at.Compare(b.at) })
	return d
}

// levelAt is the demand at now, never below 0.2 node.
func (d demand) levelAt(now time.Time) float64 {
	level := d.base
	for _, step := range d.steps {
		if !now.Before(step.at) {
			level = step.to
		}
	}
	day := 2 * math.Pi * float64(now.Unix()) / (24 * 3600)
	return max(0.2, level+d.swing*math.Sin(day+d.phase))
}

internal/capacitysim/fakes_test.go.source_text:
package capacitysim

import (
	"context"
	"fmt"
	"maps"
	"slices"
	"strings"
	"time"

	"github.com/TerraScale/ts-orchestrator/internal/authority"
	"github.com/TerraScale/ts-orchestrator/internal/entityid"
	"github.com/TerraScale/ts-orchestrator/internal/host"
	"github.com/TerraScale/ts-orchestrator/internal/nodescale"
)

// nodeMonthlyCents is the list price of one node for a month, in BRL cents.
const nodeMonthlyCents = 4100

// fakePool keeps one region's pool in memory. Grow adds an unnamed inst-… instance, and namedAt records when the
// scaler named each instance, so its host goes live one tick later.
type fakePool struct {
	now       func() time.Time
	exists    bool
	instances []nodescale.PoolInstance
	grown     int
	namedAt   map[string]time.Time // instance ID to the time the scaler named it
}

func (p *fakePool) Observe(context.Context) (nodescale.PoolState, error) {
	if !p.exists {
		return nodescale.PoolState{}, nil
	}
	return nodescale.PoolState{Exists: true, PoolID: "pool", LifecycleState: "RUNNING", Size: len(p.instances),
		Instances: slices.Clone(p.instances)}, nil
}

func (p *fakePool) Ensure(ctx context.Context, _ nodescale.Recipe) (nodescale.PoolState, error) {
	p.exists = true
	return p.Observe(ctx)
}

func (p *fakePool) Grow(_ context.Context, from int) error {
	switch size := len(p.instances); size {
	case from + 1:
		return nil
	case from:
	default:
		return fmt.Errorf("%w: pool is %d, expected %d", nodescale.ErrPoolChanged, size, from)
	}
	p.grown++
	p.instances = append(p.instances, nodescale.PoolInstance{ID: fmt.Sprintf("ocid-inst-%d", p.grown),
		Name: fmt.Sprintf("inst-%d", p.grown), State: "PROVISIONING", PrivateIP: fmt.Sprintf("10.0.9.%d", p.grown),
		Created: p.now()})
	return nil
}

func (p *fakePool) Name(_ context.Context, id, node string) error {
	i := slices.IndexFunc(p.instances, func(in nodescale.PoolInstance) bool { return in.ID == id })
	if i < 0 {
		return nodescale.ErrNotPoolInstance
	}
	p.instances[i].Name = node
	p.namedAt[id] = p.now()
	return nil
}

func (p *fakePool) Remove(_ context.Context, id string) error {
	p.instances = slices.DeleteFunc(p.instances, func(in nodescale.PoolInstance) bool { return in.ID == id })
	return nil
}

// fakeHosts lists every live node. The sim adds a node's name when its host goes live and deletes it when its
// instance is gone.
type fakeHosts struct {
	now  func() time.Time
	live map[string]bool
}

func (h *fakeHosts) ListHosts(context.Context) ([]host.HostStatus, error) {
	hosts := make([]host.HostStatus, 0, len(h.live))
	for node := range h.live {
		hosts = append(hosts, host.HostStatus{Registration: host.Registration{Node: node},
			SessionExpiresAt: h.now().Add(time.Hour)})
	}
	slices.SortFunc(hosts, func(a, b host.HostStatus) int {
		return strings.Compare(a.Registration.Node, b.Registration.Node)
	})
	return hosts, nil
}

func (h *fakeHosts) ListDesired(context.Context, string) ([]host.Desired, error) { return nil, nil }

func (h *fakeHosts) Cordon(context.Context, string) error { return nil }

func (h *fakeHosts) Unretire(context.Context, string) error { return nil }

// fakeLeader is a leader that may mutate. CanMutate reads the wall clock, so the lease is real-time, not sim time.
type fakeLeader struct{ snapshot authority.Snapshot }

func newFakeLeader() *fakeLeader {
	return &fakeLeader{snapshot: authority.Snapshot{DeploymentID: entityid.New(), Ready: true, Leader: true,
		Epoch: 7, Revision: 3, ExpiresAt: time.Now().Add(24 * time.Hour)}}
}

func (f *fakeLeader) Current() authority.Snapshot { return f.snapshot }

func (f *fakeLeader) Guard(context.Context, uint64) error { return nil }

// fakeStore keeps the record apart from the scaler's copy, as JetStream does: a load and a save each copy it, so one
// tick never shares memory with the next.
type fakeStore struct {
	record   nodescale.Record
	revision uint64
}

func (f *fakeStore) Load(context.Context) (nodescale.Record, uint64, error) {
	return cloneRecord(f.record), f.revision, nil
}

func (f *fakeStore) Save(_ context.Context, record nodescale.Record, revision uint64) (uint64, error) {
	if revision != f.revision {
		return 0, nodescale.ErrRecordChanged
	}
	f.record = cloneRecord(record)
	f.revision++
	return f.revision, nil
}

// cloneRecord copies what the scaler edits in place: the action in flight, and the pointers and map in its status.
func cloneRecord(record nodescale.Record) nodescale.Record {
	record.Action = cloneAction(record.Action)
	record.Status.InFlight = cloneAction(record.Status.InFlight)
	record.Status.Signals = maps.Clone(record.Status.Signals)
	return record
}

func cloneAction(action *nodescale.InFlight) *nodescale.InFlight {
	if action == nil {
		return nil
	}
	copied := *action
	return &copied
}

internal/capacitysim/sim_test.go.source_text:
package capacitysim

import (
	"context"
	"fmt"
	"maps"
	"math/rand/v2"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/TerraScale/ts-orchestrator/internal/budget"
	"github.com/TerraScale/ts-orchestrator/internal/decisionlog"
	"github.com/TerraScale/ts-orchestrator/internal/entityid"
	"github.com/TerraScale/ts-orchestrator/internal/nodescale"
	"github.com/TerraScale/ts-orchestrator/internal/ociregion/catalog"
)

const (
	regionCount      = 20
	homeCell         = "gru"
	quorumNodes      = 3
	partitionedIndex = 6  // this region cannot see the home from partitionFrom to partitionUntil
	rampIndex        = 11 // this region's demand ramps past the 12-node ceiling
	capNodes         = 150
	seed             = 804
	simDuration      = 48 * time.Hour
	partitionFrom    = 20 * time.Hour
	partitionUntil   = 28 * time.Hour
)

var simStart = time.Date(2026, time.October, 10, 0, 0, 0, 0, time.UTC)

// TestTwentyRegionsScaleUnderOneBudget runs 20 scalers and the home allocator for two simulated days, asserting the
// invariants on every 30-second step.
func TestTwentyRegionsScaleUnderOneBudget(t *testing.T) {
	entries := catalog.Entries()
	if len(entries) < regionCount || entries[0].Name() != homeCell {
		t.Fatalf("catalog has %d regions, first %q: need %d regions with %s first", len(entries), entries[0].Name(),
			regionCount, homeCell)
	}
	s := newSim(t, entries[:regionCount])
	steps := int(simDuration / nodescale.Interval)
	for range steps {
		s.step()
	}
	c := s.counts
	if c.scaleUps == 0 || c.scaleDowns == 0 || c.budgetHoldStarts == 0 {
		t.Fatalf("run missed a case: %d scale-ups, %d scale-downs, %d budget-capped holds",
			c.scaleUps, c.scaleDowns, c.budgetHoldStarts)
	}
	t.Logf("%d steps of %s: %d scale-ups, %d scale-downs, %d budget-capped hold starts (%d region ticks held), "+
		"%d unknown-capacity minutes, %d scale-ups in the partition's first %s, peak fleet %d of %d nodes",
		steps, nodescale.Interval, c.scaleUps, c.scaleDowns, c.budgetHoldStarts, c.budgetHoldTicks,
		c.unknownMinutes, c.partitionLaunches, budget.AllowanceMaxAge, c.peakNodes, capNodes)
}

// sim is the home allocator and the regions it allocates to, on one clock.
type sim struct {
	t       *testing.T
	now     time.Time
	budget  budget.Budget
	regions []*simRegion
	counts  simCounts

	lastAllocation time.Time        // the latest minute the home allocated
	lastReason     string           // that allocation's reason, for failure messages
	prior          *budget.Capacity // the capacity the home last wrote, nil before its first allocation
}

// simCounts is what the run observed.
type simCounts struct {
	scaleUps, scaleDowns int
	budgetHoldTicks      int // region ticks held with the budget as the reason
	budgetHoldStarts     int // holds that began on a tick after the region was not held by the budget
	unknownMinutes       int // allocations in which some region had no fresh status
	partitionLaunches    int // scale-ups the partitioned region started in the partition's first AllowanceMaxAge
	peakNodes            int
}

func newSim(t *testing.T, cells []catalog.Entry) *sim {
	s := &sim{t: t, now: simStart.Add(-nodescale.Interval), budget: budget.Budget{Schema: budget.Schema,
		ID: entityid.New(), MonthlyCapCents: capNodes * nodeMonthlyCents, Currency: "BRL", SetBy: "sim", SetAt: simStart}}
	for index, entry := range cells {
		s.regions = append(s.regions, s.newRegion(entry.Name(), index))
	}
	return s
}

func (s *sim) clock() time.Time { return s.now }

func (s *sim) stamp() string { return s.now.Format(time.RFC3339) }

// step advances one nodescale.Interval: the world moves, every scaler ticks, and on each whole minute the home
// allocates.
func (s *sim) step() {
	s.now = s.now.Add(nodescale.Interval)
	for _, r := range s.regions {
		r.world(s.now)
	}
	for _, r := range s.regions {
		if err := r.scaler.Tick(context.Background()); err != nil {
			s.t.Fatalf("%s tick at %s: %v", r.cell, s.stamp(), err)
		}
	}
	if s.now.Sub(simStart)%time.Minute == 0 {
		s.allocate()
	}
	s.check()
}

// allocate is the home's minute. It reads each region's status, except a partitioned region's, writes the capacity
// document and hands it to every region that can see the home.
func (s *sim) allocate() {
	regions := make([]budget.Region, 0, len(s.regions))
	for _, r := range s.regions {
		if r.cut(s.now) {
			regions = append(regions, budget.Region{Cell: r.cell})
			continue
		}
		st := r.scaler.Status()
		regions = append(regions, budget.Region{Cell: r.cell, Nodes: st.Nodes, Want: st.Want, Pressure: st.Pressure,
			NodeMonthlyCents: st.NodeMonthlyCents, ProjectedCents: st.ProjectedCents, Currency: st.Currency, At: st.At})
	}
	capacity := budget.Allocate(&s.budget, regions, s.prior, s.now)
	if err := capacity.Validate(); err != nil {
		s.t.Fatalf("capacity at %s is invalid: %v", s.stamp(), err)
	}
	s.prior = &capacity
	unknown := capacity.State == budget.StateUnknown
	if unknown != inPartition(s.now) {
		s.t.Fatalf("capacity at %s is %s: it must be unknown exactly during the partition. %s", s.stamp(),
			capacity.State, capacity.Reason)
	}
	if unknown {
		s.counts.unknownMinutes++
	}
	s.lastAllocation, s.lastReason = s.now, capacity.Reason
	for _, r := range s.regions {
		if !r.cut(s.now) {
			r.view, r.hasView = capacity, true
		}
	}
}

// check asserts the invariants at the end of a step.
func (s *sim) check() {
	fleet := 0
	for _, r := range s.regions {
		nodes := r.nodes()
		fleet += nodes
		if nodes < nodescale.MinNodes || nodes > nodescale.MaxNodes {
			s.t.Fatalf("%s has %d nodes at %s, want %d to %d%s", r.cell, nodes, s.stamp(), nodescale.MinNodes,
				nodescale.MaxNodes, s.dump())
		}
		s.checkEvents(r)
		s.checkPartition(r)
		st := r.scaler.Status()
		held := st.Action == nodescale.Hold && strings.Contains(st.Reason, "budget")
		if held {
			s.counts.budgetHoldTicks++
			if !r.budgetHeld {
				s.counts.budgetHoldStarts++
			}
		}
		r.budgetHeld = held
	}
	if fleetCents := uint64(fleet) * nodeMonthlyCents; fleetCents > s.budget.MonthlyCapCents {
		s.t.Fatalf("fleet spend at %s is %d cents for %d nodes, over the %d cent cap%s", s.stamp(), fleetCents,
			fleet, s.budget.MonthlyCapCents, s.dump())
	}
	s.counts.peakNodes = max(s.counts.peakNodes, fleet)
}

// checkEvents asserts each scale decision the region journaled since the last step against its cooldown. No
// scale-up may start in the partitioned region after its last capacity went stale.
func (s *sim) checkEvents(r *simRegion) {
	for _, e := range r.events[r.checked:] {
		switch e.Kind {
		case decisionlog.KindScaleUp:
			s.counts.scaleUps++
			if !r.lastChange.IsZero() && e.Time.Sub(r.lastChange) < nodescale.UpCooldown {
				s.t.Fatalf("%s scaled up at %s, %s after its last change, inside the %s up cooldown",
					r.cell, e.Time.Format(time.RFC3339), e.Time.Sub(r.lastChange), nodescale.UpCooldown)
			}
			if r.index == partitionedIndex && inPartition(e.Time) {
				if e.Time.After(simStart.Add(partitionFrom + budget.AllowanceMaxAge)) {
					s.t.Fatalf("partitioned %s scaled up at %s, after its capacity went stale", r.cell,
						e.Time.Format(time.RFC3339))
				}
				s.counts.partitionLaunches++
			}
		case decisionlog.KindScaleDown:
			s.counts.scaleDowns++
			if !r.lastChange.IsZero() && e.Time.Sub(r.lastChange) < nodescale.DownCooldown {
				s.t.Fatalf("%s scaled down at %s, %s after its last change, inside the %s down cooldown",
					r.cell, e.Time.Format(time.RFC3339), e.Time.Sub(r.lastChange), nodescale.DownCooldown)
			}
		default:
			continue
		}
		r.lastChange = e.Time
	}
	r.checked = len(r.events)
}

// checkPartition holds the partitioned region to its size once its capacity is stale: after the first ten minutes
// of the partition, it never gains a node.
func (s *sim) checkPartition(r *simRegion) {
	if r.index != partitionedIndex || !inPartition(s.now) || s.now.Before(simStart.Add(partitionFrom+10*time.Minute)) {
		return
	}
	if r.frozen == 0 {
		r.frozen = r.nodes()
	}
	if nodes := r.nodes(); nodes > r.frozen {
		s.t.Fatalf("partitioned %s grew to %d nodes at %s, above its %d at the freeze", r.cell, nodes, s.stamp(),
			r.frozen)
	}
}

// dump lists every region's nodes and status for a failure message.
func (s *sim) dump() string {
	var b strings.Builder
	for _, r := range s.regions {
		st := r.scaler.Status()
		fmt.Fprintf(&b, "\n  %s nodes=%d status_nodes=%d want=%d action=%s allowance=%d fresh=%t in_flight=%v reason=%q",
			r.cell, r.nodes(), st.Nodes, st.Want, st.Action, st.Allowance, st.AllowanceFresh, st.InFlight, st.Reason)
	}
	fmt.Fprintf(&b, "\n  last allocation at %s: %s", s.lastAllocation.Format(time.RFC3339), s.lastReason)
	return b.String()
}

// inPartition reports whether the home cannot see the partitioned region at now.
func inPartition(now time.Time) bool {
	return !now.Before(simStart.Add(partitionFrom)) && now.Before(simStart.Add(partitionUntil))
}

// simRegion is one region on fakes: its scaler, its demand, and what the home has seen from it.
type simRegion struct {
	cell       string
	index      int
	quorum     []string
	demand     demand
	pool       *fakePool
	hosts      *fakeHosts
	loads      []nodescale.NodeLoad
	store      *fakeStore
	scaler     *nodescale.Scaler
	events     []decisionlog.Decision // the scaler's journal, oldest first
	checked    int                    // events already asserted
	lastChange time.Time              // when the region last started a scale-up or scale-down
	budgetHeld bool
	frozen     int             // nodes when the partition's freeze began; 0 before
	view       budget.Capacity // the last capacity this region received
	hasView    bool
}

// newRegion starts a region with its three quorum nodes live and no pool.
func (s *sim) newRegion(cell string, index int) *simRegion {
	rng := rand.New(rand.NewPCG(seed, uint64(index)))
	r := &simRegion{cell: cell, index: index, demand: newDemand(rng, simStart, index == rampIndex),
		pool:  &fakePool{now: s.clock, namedAt: map[string]time.Time{}},
		hosts: &fakeHosts{now: s.clock, live: map[string]bool{}}, store: &fakeStore{}}
	for n := 1; n <= quorumNodes; n++ {
		node := fmt.Sprintf("ts-%s-%d", cell, n)
		r.quorum = append(r.quorum, node)
		r.hosts.live[node] = true
	}
	r.scaler = &nodescale.Scaler{
		Cell:   cell,
		Pool:   r.pool,
		Recipe: func(context.Context) (nodescale.Recipe, error) { return nodescale.Recipe{Cell: cell}, nil },
		Hosts:  r.hosts,
		Loads:  func() []nodescale.NodeLoad { return r.loads },
		Allowance: func(now time.Time) (int, bool) {
			if !r.hasView {
				return 0, false
			}
			return budget.AllowanceFor(r.view, cell, now)
		},
		Revoke:   func(context.Context, string) error { return nil },
		Backends: func(context.Context, string, string) (int, error) { return 0, nil },
		Journal:  func(_ context.Context, decision decisionlog.Decision) { r.events = append(r.events, decision) },
		Cost: func(_ context.Context, pool nodescale.PoolState) (nodescale.Cost, error) {
			nodes := quorumNodes + len(pool.Instances)
			return nodescale.Cost{NodeMonthlyCents: nodeMonthlyCents, ProjectedCents: uint64(nodes) * nodeMonthlyCents,
				Currency: "BRL", At: s.now}, nil
		},
		Leader: newFakeLeader(),
		Store:  r.store,
		Now:    s.clock,
	}
	return r
}

// nodes is the region's node count as OCI shows it: the quorum and every pool instance.
func (r *simRegion) nodes() int { return quorumNodes + len(r.pool.instances) }

// cut reports whether the home cannot see this region at now.
func (r *simRegion) cut(now time.Time) bool { return r.index == partitionedIndex && inPartition(now) }

// world moves the region to now. A node named at an earlier tick goes live, a removed instance's host goes away,
// and every live node reports the region's load: CPU = min(1, demand/nodes), memory and disk lower.
func (r *simRegion) world(now time.Time) {
	for _, in := range r.pool.instances {
		if named, ok := r.pool.namedAt[in.ID]; ok && now.After(named) {
			r.hosts.live[in.Name] = true
		}
	}
	for node := range r.hosts.live {
		gone := !slices.ContainsFunc(r.pool.instances, func(in nodescale.PoolInstance) bool { return in.Name == node })
		if gone && !slices.Contains(r.quorum, node) {
			delete(r.hosts.live, node)
		}
	}
	cpu := min(1, r.demand.levelAt(now)/float64(r.nodes()))
	r.loads = nil
	for _, node := range slices.Sorted(maps.Keys(r.hosts.live)) {
		r.loads = append(r.loads, nodescale.NodeLoad{Node: node, At: now, CPU: cpu, Memory: 0.8 * cpu,
			Disk: 0.3 * cpu, Cores: 4})
	}
}

internal/capacitysim/suggestions_test.go.source_text:
package capacitysim

import (
	"math/rand/v2"
	"slices"
	"testing"
	"time"

	"github.com/TerraScale/ts-orchestrator/internal/nodescale"
	"github.com/TerraScale/ts-orchestrator/internal/ociregion/catalog"
	"github.com/TerraScale/ts-orchestrator/internal/regionsuggest"
)

const (
	suggestDays     = 40
	candidateCount  = 10
	idleFrom        = 15 // cells idleFrom to idleFrom+idleCount-1 sit at the starting size for the whole run
	idleCount       = 4
	suggestHeadroom = 100 * 3 * nodeMonthlyCents
)

// TestRegionSuggestionsOverFortyDays runs the suggester alone for 40 simulated days over 20 serving regions and 10
// candidates. Nothing acts on a suggestion, so the regions stay as they are, and the run asserts the rules at every round.
func TestRegionSuggestionsOverFortyDays(t *testing.T) {
	entries := catalog.Entries()
	used := regionCount + candidateCount
	if len(entries) < used || entries[0].Name() != homeCell {
		t.Fatalf("catalog has %d regions, first %q: need %d regions with %s first", len(entries), entries[0].Name(),
			used, homeCell)
	}
	end := simStart.Add(suggestDays * 24 * time.Hour)
	cells := make(map[string]*simCell, used)
	for index, entry := range entries[:used] {
		rng := rand.New(rand.NewPCG(seed, uint64(index)+1))
		c := &simCell{cell: entry.Name(), rng: rng,
			idle: index >= idleFrom && index < idleFrom+idleCount}
		if !c.idle {
			c.bursts = burstsFor(rng, simStart, end)
		}
		cells[c.cell] = c
	}

	var candidates []regionsuggest.Candidate
	for _, entry := range entries[regionCount:used] {
		candidates = append(candidates, regionsuggest.Candidate{Cell: entry.Name(), OCIRegion: entry.OCIRegion})
	}
	guard := regionsuggest.Budget{HeadroomCents: suggestHeadroom, RegionMonthlyCents: 3 * nodeMonthlyCents, Currency: "BRL"}
	var memory regionsuggest.Memory
	var adds, removes int
	for now := simStart; now.Before(end); now = now.Add(regionsuggest.Interval) {
		regions := []regionsuggest.Region{regionFor(cells[homeCell], entries[0].OCIRegion, now, true)}
		for _, entry := range entries[1:regionCount] {
			regions = append(regions, regionFor(cells[entry.Name()], entry.OCIRegion, now, false))
		}
		var suggestion regionsuggest.Suggestion
		suggestion, memory = regionsuggest.Suggest(regions, candidates, memory, guard, now)
		switch suggestion.Action {
		case regionsuggest.ActionAdd:
			if suggestion.OCIRegion == "" || suggestion.MonthlyCents != 3*nodeMonthlyCents {
				t.Fatalf("add %+v at %s names no region or misprices it", suggestion, now.Format(time.RFC3339))
			}
			adds++
		case regionsuggest.ActionRemove:
			if suggestion.Cell == homeCell {
				t.Fatalf("suggested removing the home %s at %s", homeCell, now.Format(time.RFC3339))
			}
			if len(regions) <= regionsuggest.MinRegions {
				t.Fatalf("suggested removing %s with %d regions; MinRegions is %d", suggestion.Cell, len(regions),
					regionsuggest.MinRegions)
			}
			if !cells[suggestion.Cell].idle || now.Sub(memory.IdleSince[suggestion.Cell]) < regionsuggest.IdleFor {
				t.Fatalf("suggested removing %s at %s, which has not been idle for %v", suggestion.Cell,
					now.Format(time.RFC3339), regionsuggest.IdleFor)
			}
			removes++
		}
	}
	if adds == 0 || removes == 0 {
		t.Fatalf("run missed a case: %d add rounds, %d remove rounds over %d days", adds, removes, suggestDays)
	}
	t.Logf("%d days of %s suggestions: %d add rounds, %d remove rounds", suggestDays, regionsuggest.Interval, adds, removes)
}

// simCell is one catalog cell's synthetic status: idle at the starting size, or busy with saturated bursts.
type simCell struct {
	cell   string
	idle   bool
	bursts []window
	rng    *rand.Rand
}

// window is the span [from, until).
type window struct{ from, until time.Time }

// status is the cell's synthetic scaling status at now.
func (c *simCell) status(now time.Time) nodescale.Status {
	st := nodescale.Status{Schema: nodescale.StatusSchema, Cell: c.cell, At: now, Nodes: 5, Currency: "BRL",
		NodeMonthlyCents: nodeMonthlyCents, Reason: "synthetic status"}
	level := 0.5
	switch {
	case c.idle:
		st.Nodes, level = 3, 0.04
	case c.saturated(now):
		st.Nodes, st.Saturated, level = 12, true, 0.9
	}
	st.Signals = map[nodescale.Signal]float64{}
	for _, sig := range nodescale.Signals {
		st.Signals[sig] = level + 0.05*c.rng.Float64()
	}
	return st
}

func (c *simCell) saturated(now time.Time) bool {
	return slices.ContainsFunc(c.bursts, func(w window) bool { return !now.Before(w.from) && now.Before(w.until) })
}

// burstsFor draws a busy cell's saturated spans from start to end. Each lasts 2 to 6 hours, and they recur a day
// or more apart.
func burstsFor(rng *rand.Rand, start, end time.Time) []window {
	var bursts []window
	for at := start.Add(time.Duration(rng.Int64N(int64(48 * time.Hour)))); at.Before(end); {
		length := 2*time.Hour + time.Duration(rng.Int64N(int64(4*time.Hour)))
		bursts = append(bursts, window{from: at, until: at.Add(length)})
		at = at.Add(length + 24*time.Hour + time.Duration(rng.Int64N(int64(72*time.Hour))))
	}
	return bursts
}

// regionFor is the suggester's view of one serving cell at now.
func regionFor(c *simCell, ociRegion string, now time.Time, home bool) regionsuggest.Region {
	st := c.status(now)
	return regionsuggest.Region{Cell: c.cell, OCIRegion: ociRegion, Home: home, Status: &st}
}

internal/globalcontrol/document.go.source_text:
package globalcontrol

import (
	"context"
	"errors"
	"log/slog"
	"time"

	"github.com/TerraScale/ts-orchestrator/internal/observability"
	"github.com/TerraScale/ts-orchestrator/internal/protocol"
	"github.com/nats-io/nats.go/jetstream"
)

// Document is a document the home region relays to every region. A
// KindCellSpec document is the exact bytes an operator submitted for one
// regional cell: the relay adds no authority, the global writer only orders
// and fences the record, and every region verifies the bytes against its own
// trust roots before acting on them, so a document no region would accept
// from an operator directly is refused the same way when it arrives through
// the mirror. KindBudget and KindCapacity are the global writer's own
// documents under the global cell, trusted like the roster.
type Document struct {
	Payload []byte
	// Generation counts the record's payloads; it is not the document's
	// own generation, which only its verifier may trust.
	Generation uint64
	Epoch      uint64
	Sequence   uint64
}

var errDocumentKey = errors.New("global document needs a document kind and a matching cell")

func validDocument(kind Kind, cell string) bool {
	switch kind {
	case KindCellSpec:
		return cellToken.MatchString(cell) && cell != protocol.GlobalScope
	case KindBudget, KindCapacity:
		return cell == protocol.GlobalScope
	}
	return false
}

// PutDocument relays payload for cell as kind's next generation. A payload
// equal to the stored one is an idempotent retry. admit, when set, sees the
// stored payload (nil when there is none) and may refuse the write; the
// append is conditional on that exact record, so no other write can land
// between the check and the append.
func (w *Writer) PutDocument(ctx context.Context, epoch uint64, kind Kind, cell string, payload []byte,
	admit func(prior []byte) error,
) (uint64, error) {
	if !validDocument(kind, cell) {
		return 0, errDocumentKey
	}
	if len(payload) == 0 || len(payload) > maxRecordBytes {
		return 0, errors.New("global document must hold 1 byte to 64 KiB")
	}
	return w.put(ctx, epoch, kind, cell, 0, payload, admit)
}

// Document returns kind's current document for cell.
func (r *Reader) Document(ctx context.Context, kind Kind, cell string) (Document, error) {
	if !validDocument(kind, cell) {
		return Document{}, errDocumentKey
	}
	stored, sequence, err := r.read(ctx, kind, cell)
	if err != nil {
		return Document{}, err
	}
	if len(stored.Payload) == 0 || len(stored.Payload) > maxRecordBytes {
		return Document{}, ErrRecordCorrupt
	}
	return Document{Payload: stored.Payload, Generation: stored.Generation, Epoch: stored.Epoch, Sequence: sequence}, nil
}

// Follow offers kind's current document for cell to apply when Follow
// starts, each time the record changes and every recheck, so apply must be
// idempotent: a document the caller cannot act on yet, on a follower or
// after a transient error, is simply offered again. A watch on the local
// stream (the home stream or this region's mirror) makes changes immediate;
// every read is still the verified read, so a mirror missing home records
// offers nothing. Failures are logged once each. Follow returns when ctx
// ends.
func (r *Reader) Follow(ctx context.Context, kind Kind, cell string, recheck time.Duration,
	apply func(context.Context, Document),
) error {
	if !validDocument(kind, cell) {
		return errDocumentKey
	}
	if recheck <= 0 {
		return errors.New("global document recheck must be positive")
	}
	changed := make(chan struct{}, 1)
	var watch jetstream.ConsumeContext
	defer func() {
		if watch != nil {
			watch.Stop()
		}
	}()
	ticker := time.NewTicker(recheck)
	defer ticker.Stop()
	var failure string
	for {
		var watchErr error
		if watch == nil {
			watch, watchErr = r.watch(ctx, subject(kind, cell), changed)
		}
		document, err := r.Document(ctx, kind, cell)
		switch {
		case err == nil:
			apply(ctx, document)
		case errors.Is(err, ErrNotFound):
			err = nil
		}
		if err = errors.Join(watchErr, err); err != nil && err.Error() != failure && ctx.Err() == nil {
			slog.WarnContext(ctx, "global document unavailable", observability.ComponentKey, "globalcontrol",
				"kind", kind, "cell", cell, "error", err)
		}
		failure = ""
		if err != nil {
			failure = err.Error()
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-changed:
		case <-ticker.C:
		}
	}
}

// watch signals changed for every record stored on subject, starting with
// the current one, through an ordered consumer on the local stream.
func (r *Reader) watch(ctx context.Context, subject string, changed chan<- struct{}) (jetstream.ConsumeContext, error) {
	if r == nil || r.stream == nil {
		return nil, errors.New("global control reader is not open")
	}
	createCtx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()
	consumer, err := r.stream.OrderedConsumer(createCtx, jetstream.OrderedConsumerConfig{
		FilterSubjects: []string{subject}, DeliverPolicy: jetstream.DeliverLastPerSubjectPolicy,
	})
	if err != nil {
		return nil, err
	}
	return consumer.Consume(func(jetstream.Msg) {
		select {
		case changed <- struct{}{}:
		default:
		}
	})
}

internal/globalcontrol/store.go.source_text:
package globalcontrol

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"strconv"
	"sync"

	"github.com/TerraScale/ts-orchestrator/internal/entityid"

	"github.com/TerraScale/ts-orchestrator/internal/authority"
	"github.com/TerraScale/ts-orchestrator/internal/protocol"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
)

var (
	ErrNotFound       = errors.New("global record not found")
	ErrConflict       = errors.New("global record compare-and-set conflict")
	ErrStaleRecord    = errors.New("global record generation does not advance")
	ErrNotHomeRegion  = errors.New("global state is writable only in the home region")
	ErrRecordCorrupt  = errors.New("global record is corrupt")
	ErrRosterRequired = errors.New("global directory writes require a region roster")
	// ErrMirrorGap means a regional mirror is missing home records. The home
	// stream never loses a record (no deletes, purges or limits), so a gap
	// means the mirror's durable consumer was reset past records the mirror
	// had not stored, for example by a compromised leaf credential of that
	// region sending a forward reset. The mirror fails closed rather than serve a record that
	// a skipped one may have superseded; recreate the mirror to recover.
	ErrMirrorGap = errors.New("global mirror is missing home records")
	// ErrMirrorNotCaughtUp means an empty regional mirror has not yet
	// confirmed with the home stream that there is nothing to copy.
	ErrMirrorNotCaughtUp = errors.New("global mirror has not caught up with the home stream")
)

// record is the stored envelope. Epoch is the global authority epoch that
// guarded the write; readers reject a record whose epoch regresses relative
// to the record it replaced.
type record struct {
	Version    int    `json:"version"`
	Kind       Kind   `json:"kind"`
	Key        string `json:"key"`
	Generation uint64 `json:"generation"`
	Epoch      uint64 `json:"epoch"`
	Payload    []byte `json:"payload"`
}

func subject(kind Kind, key string) string { return protocol.GlobalState(string(kind), key) }

// Reader serves global records from the home stream or a regional mirror.
type Reader struct {
	stream jetstream.Stream
	// js reads the stream's info through a fresh handle: Info on stream
	// would rewrite the handle's cached info, which concurrent reads use.
	js jetstream.JetStream
	// mirror makes every read prove that the mirror holds a gap-free prefix
	// of the home stream (see ErrMirrorGap).
	mirror bool
}

// Roster returns the current region roster and its stream sequence.
func (r *Reader) Roster(ctx context.Context) (Roster, uint64, error) {
	var roster Roster
	entry, sequence, err := r.read(ctx, KindRoster, RosterKey)
	if err != nil {
		return Roster{}, 0, err
	}
	if err := protocol.DecodeStrict(entry.Payload, &roster, maxRecordBytes); err != nil ||
		roster.Validate() != nil || roster.Generation != entry.Generation {
		return Roster{}, 0, ErrRecordCorrupt
	}
	return roster, sequence, nil
}

// Directory returns a database partition's directory entry.
func (r *Reader) Directory(ctx context.Context, databaseID, partitionID string) (DirectoryEntry, uint64, error) {
	var directory DirectoryEntry
	if !entityid.Valid(databaseID) || !entityid.Valid(partitionID) {
		return DirectoryEntry{}, 0, errors.New("directory database and partition must be canonical ULIDs")
	}
	key := DirectoryKey(databaseID, partitionID)
	entry, sequence, err := r.read(ctx, KindDirectory, key)
	if err != nil {
		return DirectoryEntry{}, 0, err
	}
	if err := protocol.DecodeStrict(entry.Payload, &directory, maxRecordBytes); err != nil ||
		directory.Validate() != nil || directory.Generation != entry.Generation ||
		directory.DatabaseID != databaseID || directory.PartitionID != partitionID {
		return DirectoryEntry{}, 0, ErrRecordCorrupt
	}
	return directory, sequence, nil
}

func (r *Reader) read(ctx context.Context, kind Kind, key string) (record, uint64, error) {
	if r == nil || r.stream == nil {
		return record{}, 0, errors.New("global control reader is not open")
	}
	readCtx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()
	message, err := r.stream.GetLastMsgForSubject(readCtx, subject(kind, key))
	if r.mirror && (err == nil || errors.Is(err, jetstream.ErrMsgNotFound)) {
		// Checked after the read: no gap up to the mirror's last sequence
		// now means no newer record for this subject was skipped before it.
		if gapErr := r.checkMirrorGapFree(readCtx); gapErr != nil {
			return record{}, 0, gapErr
		}
	}
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return record{}, 0, ErrNotFound
	}
	if err != nil {
		return record{}, 0, err
	}
	var stored record
	if err := protocol.DecodeStrict(message.Data, &stored, maxMessageBytes); err != nil ||
		stored.Version != recordVersion || stored.Kind != kind || stored.Key != key ||
		stored.Generation == 0 || stored.Epoch == 0 {
		return record{}, 0, ErrRecordCorrupt
	}
	if !epochHeaderMatches(message.Header, stored.Epoch) {
		return record{}, 0, ErrRecordCorrupt
	}
	return stored, message.Sequence, nil
}

// checkMirrorGapFree requires the mirror to hold every home sequence from 1
// to its last one. Skipped sequences show up as deleted messages or as a
// first sequence beyond 1.
func (r *Reader) checkMirrorGapFree(ctx context.Context) error {
	info, err := r.info(ctx)
	if err != nil {
		return fmt.Errorf("inspect global mirror: %w", err)
	}
	state := info.State
	if state.LastSeq == 0 {
		// An empty mirror proves nothing until it has heard from the home
		// stream and has nothing left to copy: before its first contact
		// (initial catch-up, or a home that never created this region's
		// mirror consumer) "not found" would be a guess.
		if mirror := info.Mirror; mirror == nil || mirror.Active < 0 || mirror.Lag != 0 {
			return ErrMirrorNotCaughtUp
		}
		return nil
	}
	if state.NumDeleted != 0 || state.FirstSeq != 1 || state.Msgs != state.LastSeq {
		return ErrMirrorGap
	}
	return nil
}

// info is the stream's current info, read without touching r.stream.
func (r *Reader) info(ctx context.Context) (*jetstream.StreamInfo, error) {
	stream, err := r.js.Stream(ctx, r.stream.CachedInfo().Config.Name)
	if err != nil {
		return nil, err
	}
	return stream.CachedInfo(), nil
}

// EpochHeader carries the global authority epoch of every record the writer
// appends, term barriers included. It must equal the epoch in the record
// body; a reader treats a mismatch as corruption.
const EpochHeader = "Ts-Global-Epoch"

// termKey is the single key of the term barrier record.
const termKey = "current"

// maxAppendAttempts bounds compare-and-set retries against concurrent appends.
const maxAppendAttempts = 8

// epochHeaderMatches accepts a record whose epoch header equals its body. A
// record without the header was not appended by a Writer.
func epochHeaderMatches(header nats.Header, epoch uint64) bool {
	return header.Get(EpochHeader) == strconv.FormatUint(epoch, 10)
}

// term is the payload of the barrier record a new global leader appends to
// TS_GLOBAL_CONTROL before its first write.
type term struct {
	Epoch uint64 `json:"epoch"`
}

// Writer appends global records in the home region.
//
// Fencing is enforced by the server, not only by the pre-publish lease
// Guard: the global stream and the authority lease live in different streams,
// so a Guard alone cannot order a write against a newer term. The writer
// therefore keeps a term barrier inside TS_GLOBAL_CONTROL itself
// (ts.global.v1.term.current). A writer whose lease epoch is newer than the
// stored term first appends a barrier for its epoch (per-subject CAS on the
// term subject, and only right after a successful lease Guard), and every
// record append is a whole-stream compare-and-set on the last sequence at
// which the writer saw its own epoch as the current term, plus the
// per-subject CAS on the record. Once a new leader appends its barrier, every
// in-flight append of an older leader fails with a wrong-last-sequence error,
// and its retry observes the newer term and returns authority.ErrFenced. An
// old leader that commits before the new barrier is ordered before the new
// term, which reads every record after its own barrier.
type Writer struct {
	Reader
	home   string
	fencer authority.Fencer
	// replicas is the replica count OpenHome verified; every append
	// re-verifies the stream against it, so later drift is detected.
	replicas int
	mu       sync.Mutex
	// beforePublish runs between the fenced reads and the conditional
	// append; tests use it to interleave a new term.
	beforePublish func()
}

// OpenHome creates or verifies the writable home stream and the durable
// mirror consumer of every peer that mirrors it. cell must equal the roster
// home; fencer must be the global-scope authority runtime. Mirror consumers of
// regions that are no longer peers are deleted.
func OpenHome(ctx context.Context, js jetstream.JetStream, cell string, peers []string, replicas int,
	fencer authority.Fencer,
) (*Writer, error) {
	if !cellToken.MatchString(cell) {
		return nil, errors.New("global home cell is invalid")
	}
	if err := validMirrorPeers(cell, peers); err != nil {
		return nil, err
	}
	if fencer == nil || fencer.Current().Scope != protocol.GlobalScope {
		return nil, errors.New("global writes require the global-scope authority")
	}
	stream, err := openStream(ctx, js, HomeStreamConfig(replicas), func(actual jetstream.StreamConfig) error {
		return verifyHome(actual, replicas)
	})
	if err != nil {
		return nil, err
	}
	if err := ensureMirrorConsumers(ctx, stream, peers, replicas); err != nil {
		return nil, err
	}
	if err := removeStaleMirrorConsumers(ctx, stream, peers); err != nil {
		return nil, err
	}
	return &Writer{Reader: Reader{stream: stream, js: js}, home: cell, fencer: fencer, replicas: replicas}, nil
}

// validMirrorPeers requires every peer to be a regional cell other than home.
func validMirrorPeers(home string, peers []string) error {
	for _, peer := range peers {
		if !cellToken.MatchString(peer) || peer == protocol.GlobalScope || peer == home {
			return fmt.Errorf("global mirror peer %q is invalid", peer)
		}
	}
	return nil
}

// PutRoster writes the next roster generation. The home region cannot be
// moved through this path; a home transfer needs an operator-signed envelope.
func (w *Writer) PutRoster(ctx context.Context, epoch uint64, roster Roster) (uint64, error) {
	if err := roster.Validate(); err != nil {
		return 0, err
	}
	if roster.HomeRegion != w.home {
		return 0, ErrNotHomeRegion
	}
	payload, err := protocol.EncodeJSON(roster)
	if err != nil {
		return 0, err
	}
	return w.put(ctx, epoch, KindRoster, RosterKey, roster.Generation, payload, nil)
}

// PutDirectory writes the next generation of a partition's directory entry.
// Every active region must be Active in the current roster.
func (w *Writer) PutDirectory(ctx context.Context, epoch uint64, entry DirectoryEntry) (uint64, error) {
	roster, _, err := w.Roster(ctx)
	if errors.Is(err, ErrNotFound) {
		return 0, ErrRosterRequired
	}
	if err != nil {
		return 0, err
	}
	if err := entry.ValidateAgainst(roster); err != nil {
		return 0, err
	}
	payload, err := protocol.EncodeJSON(entry)
	if err != nil {
		return 0, err
	}
	return w.put(ctx, epoch, KindDirectory, entry.Key(), entry.Generation, payload, nil)
}

// Fence appends the term barrier for epoch unless the stream already holds
// it. A new global leader calls it eagerly so that no older leader can append
// once it returns; every write also establishes the term first.
func (w *Writer) Fence(ctx context.Context, epoch uint64) error {
	if epoch == 0 {
		return authority.ErrFenced
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	if err := w.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err := w.establishTerm(ctx, epoch)
	return err
}

// Term returns the epoch of the latest term barrier, or 0 before the first.
func (r *Reader) Term(ctx context.Context) (uint64, error) {
	if r == nil || r.stream == nil {
		return 0, errors.New("global control reader is not open")
	}
	readCtx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()
	epoch, _, err := readTerm(readCtx, r.stream)
	if err == nil && r.mirror {
		// Like every mirror read: a mirror missing home records may also
		// miss a newer barrier, so it fails closed.
		if gapErr := r.checkMirrorGapFree(readCtx); gapErr != nil {
			return 0, gapErr
		}
	}
	return epoch, err
}

func readTerm(ctx context.Context, stream jetstream.Stream) (uint64, uint64, error) {
	message, err := stream.GetLastMsgForSubject(ctx, subject(KindTerm, termKey))
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return 0, 0, nil
	}
	if err != nil {
		return 0, 0, err
	}
	var stored record
	var barrier term
	if err := protocol.DecodeStrict(message.Data, &stored, maxMessageBytes); err != nil ||
		stored.Version != recordVersion || stored.Kind != KindTerm || stored.Key != termKey ||
		stored.Epoch == 0 || stored.Generation != stored.Epoch || !epochHeaderMatches(message.Header, stored.Epoch) ||
		protocol.DecodeStrict(stored.Payload, &barrier, 1024) != nil || barrier.Epoch != stored.Epoch {
		return 0, 0, ErrRecordCorrupt
	}
	return stored.Epoch, message.Sequence, nil
}

// establishTerm makes epoch the stored term and returns a stream last
// sequence at which it was current. The caller holds w.mu and has just
// guarded epoch against the authority lease.
func (w *Writer) establishTerm(ctx context.Context, epoch uint64) (uint64, error) {
	for range maxAppendAttempts {
		readCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		info, err := w.info(readCtx)
		if err != nil {
			cancel()
			return 0, fmt.Errorf("read global stream sequence: %w", err)
		}
		if err := verifyHome(info.Config, w.replicas); err != nil {
			cancel()
			return 0, err
		}
		current, termSequence, err := readTerm(readCtx, w.stream)
		cancel()
		if err != nil {
			return 0, fmt.Errorf("read global term: %w", err)
		}
		if termSequence > info.State.LastSeq {
			continue
		}
		switch {
		case current == epoch:
			return info.State.LastSeq, nil
		case current > epoch:
			return 0, authority.ErrFenced
		}
		payload, err := protocol.EncodeJSON(term{Epoch: epoch})
		if err != nil {
			return 0, err
		}
		data, err := protocol.EncodeJSON(record{
			Version: recordVersion, Kind: KindTerm, Key: termKey, Generation: epoch, Epoch: epoch, Payload: payload,
		})
		if err != nil {
			return 0, err
		}
		message := nats.NewMsg(subject(KindTerm, termKey))
		message.Data = data
		message.Header.Set(EpochHeader, strconv.FormatUint(epoch, 10))
		publishCtx, publishCancel := context.WithTimeout(ctx, apiTimeout)
		_, err = w.js.PublishMsg(publishCtx, message,
			jetstream.WithExpectStream(StreamName),
			jetstream.WithExpectLastSequenceForSubject(termSequence, subject(KindTerm, termKey)),
		)
		publishCancel()
		if err != nil && !wrongLastSequence(err) {
			return 0, fmt.Errorf("publish global term barrier: %w", err)
		}
		// Re-read: our barrier or a concurrent newer one is now current.
	}
	return 0, ErrConflict
}

// wrongLastSequence reports a failed sequence expectation. The server also
// answers the per-subject expectation with the "constant" variant when the
// subject is in flight in a batch, which is the same concurrent-writer race.
func wrongLastSequence(err error) bool {
	apiErr, ok := errors.AsType[*jetstream.APIError](err)
	return ok && (apiErr.ErrorCode == jetstream.JSErrCodeStreamWrongLastSequence ||
		apiErr.ErrorCode == jetstream.JSErrCodeStreamWrongLastSequenceConstant)
}

// put appends payload as the record's next generation. Generation 0 means
// the stored generation plus one: an identical payload is then a retry, and
// any other payload is the next generation. admit, when set, may refuse
// the write after seeing the stored payload the append is conditional on.
func (w *Writer) put(ctx context.Context, epoch uint64, kind Kind, key string, generation uint64, payload []byte,
	admit func(prior []byte) error,
) (uint64, error) {
	if epoch == 0 {
		return 0, authority.ErrFenced
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	if err := w.fencer.Guard(ctx, epoch); err != nil {
		return 0, err
	}
	for range maxAppendAttempts {
		lastSequence, err := w.establishTerm(ctx, epoch)
		if err != nil {
			return 0, err
		}
		next := max(generation, 1)
		prior, priorSequence, err := w.read(ctx, kind, key)
		switch {
		case errors.Is(err, ErrNotFound):
		case err != nil:
			return 0, err
		case priorSequence > lastSequence:
			continue
		case (generation == 0 || prior.Generation == generation) && bytes.Equal(prior.Payload, payload):
			// An identical retry after an unknown publish outcome is idempotent.
			return priorSequence, nil
		case generation == 0:
			next = prior.Generation + 1
		case generation <= prior.Generation:
			return 0, ErrStaleRecord
		}
		if epoch < prior.Epoch {
			return 0, authority.ErrFenced
		}
		if admit != nil {
			if err := admit(prior.Payload); err != nil {
				return 0, err
			}
		}
		data, err := protocol.EncodeJSON(record{
			Version: recordVersion, Kind: kind, Key: key, Generation: next, Epoch: epoch, Payload: payload,
		})
		if err != nil {
			return 0, err
		}
		if w.beforePublish != nil {
			w.beforePublish()
		}
		message := nats.NewMsg(subject(kind, key))
		message.Data = data
		message.Header.Set(EpochHeader, strconv.FormatUint(epoch, 10))
		publishCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		ack, err := w.js.PublishMsg(publishCtx, message,
			jetstream.WithExpectStream(StreamName),
			jetstream.WithExpectLastSequence(lastSequence),
			jetstream.WithExpectLastSequenceForSubject(priorSequence, subject(kind, key)),
			jetstream.WithMsgID(string(kind)+"."+key+"."+strconv.FormatUint(next, 10)),
		)
		cancel()
		if wrongLastSequence(err) {
			// Another append won: a newer term barrier or a concurrent write.
			// The next attempt observes it and fences or re-checks the CAS.
			continue
		}
		if err != nil {
			return 0, fmt.Errorf("publish global %s record: %w", kind, err)
		}
		if ack.Duplicate {
			// The message ID was seen; only an identical stored record is success.
			stored, sequence, readErr := w.read(ctx, kind, key)
			if readErr != nil || stored.Generation != next || !bytes.Equal(stored.Payload, payload) {
				return 0, ErrConflict
			}
			return sequence, nil
		}
		return ack.Sequence, nil
	}
	return 0, ErrConflict
}

